insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('double-standard-technique-sheet', 'Double Standard Technique Sheet', 'cbt'::resource_kind, 'Sets the standard a client applies to themselves next to the one they''d offer a friend.', 'Use it to soften harsh self-judgment by testing it against a kinder standard already in use.', array['Adults']::text[], '20 minutes', 'Ask the client to describe a recent situation where they judged themselves harshly, then to imagine a friend in the identical situation and write out what they''d actually say to that friend. The gap between the two columns is the point — most clients apply a standard to themselves they''d never accept as fair for anyone else, and naming that gap out loud does more than any argument about the thought''s accuracy.', '[{"id": "f0", "type": "textarea", "label": "The situation I judged myself harshly for"}, {"id": "f1", "type": "textarea", "label": "What I said to myself about it"}, {"id": "f2", "type": "textarea", "label": "A friend in the exact same situation"}, {"id": "f3", "type": "textarea", "label": "What I would actually say to that friend"}, {"id": "f4", "type": "textarea", "label": "One sentence closer to fair I can say to myself"}]'::jsonb, array['self-criticism', 'thought record', 'self-compassion']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('structured-problem-solving-worksheet', 'Structured Problem-Solving Worksheet', 'cbt'::resource_kind, 'Walks a client through defining a problem, generating options, and picking one to try.', 'Use it to replace circular worrying about a problem with a concrete, testable next step.', array['Adults', 'Teens']::text[], '25 minutes', 'This works best on a problem the client has been turning over without acting on, not a crisis needing an immediate decision. The brainstorming step should stay judgment-free — write down every option including bad ones — since clients who edit as they go tend to land back on the option they already rejected. Set a date to review what happened with the option they picked.', '[{"id": "f0", "type": "textarea", "label": "The problem, stated in one specific sentence"}, {"id": "f1", "type": "textarea", "label": "Every option I can think of, including bad ones"}, {"id": "f2", "type": "textarea", "label": "Pros and cons of my top two options"}, {"id": "f3", "type": "textarea", "label": "The option I will try"}, {"id": "f4", "type": "textarea", "label": "My first concrete step"}, {"id": "f5", "type": "textarea", "label": "Date I will review how it went"}]'::jsonb, array['problem solving', 'decisions', 'planning']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('habit-reversal-planner', 'Habit Reversal Planner', 'cbt'::resource_kind, 'Pairs an unwanted habit with an early warning sign and a competing response to use instead.', 'Use it to interrupt an automatic habit at the moment it usually starts, not after.', array['Adults', 'Teens']::text[], '20 minutes', 'Start with awareness before change: have the client track the habit for a few days first so the early warning sign is specific rather than guessed at. The competing response should be something physically incompatible with the habit and easy to do without planning, since anything that requires setup will get skipped in the moment it''s actually needed.', '[{"id": "f0", "type": "textarea", "label": "The habit I want to change"}, {"id": "f1", "type": "textarea", "label": "What usually happens right before it (place, feeling, time)"}, {"id": "f2", "type": "textarea", "label": "My earliest warning sign that it''s about to happen"}, {"id": "f3", "type": "textarea", "label": "A competing response I can do instead"}, {"id": "f4", "type": "textarea", "label": "Who I''ve told about this plan"}, {"id": "f5", "type": "textarea", "label": "How this week went"}]'::jsonb, array['habits', 'self-monitoring', 'behavioral']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('procrastination-value-timeline', 'Procrastination Value Timeline', 'cbt'::resource_kind, 'Compares how good delay feels right now against the cost the client expects later.', 'Use it to make the short-term relief of putting something off visible against its real cost.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients rarely lack the reasoning to see that delay has a cost — the problem is that the reasoning arrives too late, after the relief of avoiding the task has already been felt. Filling this out ahead of a task the client is likely to delay again gives them something concrete to reread at the moment they reach for the delay instead.', '[{"id": "f0", "type": "textarea", "label": "The task I keep delaying"}, {"id": "f1", "type": "textarea", "label": "How doing it now would feel in the next ten minutes"}, {"id": "f2", "type": "textarea", "label": "How delaying it will feel in the next ten minutes"}, {"id": "f3", "type": "textarea", "label": "What delaying it will cost me by this time next week"}, {"id": "f4", "type": "textarea", "label": "The smallest first step I could take right now"}]'::jsonb, array['procrastination', 'time management', 'motivation']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('should-statement-rewrite-sheet', 'Should Statement Rewrite Sheet', 'cbt'::resource_kind, 'Catches a client''s rigid should statements and rewrites them as a preference instead.', 'Use it to loosen the guilt and pressure that rigid should statements tend to create.', array['Adults']::text[], '15 minutes', 'Collect a handful of the client''s own should statements before the session rather than inventing examples, since the rewrite lands better on language they actually use. Walk through why the rigid version generates guilt or resentment even when the underlying goal is reasonable, then rewrite it as something the client wants rather than something they''re required to do.', '[{"id": "f0", "type": "textarea", "label": "A should statement I say to myself often"}, {"id": "f1", "type": "textarea", "label": "Where I think this rule came from"}, {"id": "f2", "type": "textarea", "label": "What it costs me to hold it this rigidly"}, {"id": "f3", "type": "textarea", "label": "A rewrite as a preference instead of a rule"}, {"id": "f4", "type": "textarea", "label": "How it felt to say the rewrite out loud"}]'::jsonb, array['thinking traps', 'self-criticism', 'cognitive flexibility']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('silly-voice-defusion-practice', 'Silly Voice Defusion Practice', 'act'::resource_kind, 'Has a client say a sticky thought aloud in a silly voice to loosen its grip.', 'Use it to shift a client''s relationship to a thought without arguing over whether it''s true.', array['Adults', 'Teens']::text[], '10 minutes', 'Pick a thought the client already knows isn''t fully accurate but that still pulls at them, then have them say it in a cartoon voice, a slow-motion voice, and their own voice back to back. Some clients laugh, some feel silly and resist — both are useful to discuss. The point isn''t to make the thought funny forever, just to prove in the room that its grip can loosen without the content changing at all.', '[{"id": "f0", "type": "textarea", "label": "The thought that keeps pulling at me"}, {"id": "f1", "type": "textarea", "label": "How it felt to hear it in a silly voice"}, {"id": "f2", "type": "textarea", "label": "How much it felt like ''the truth'' before, out of ten"}, {"id": "f3", "type": "textarea", "label": "How much it felt like ''the truth'' just after, out of ten"}, {"id": "f4", "type": "textarea", "label": "When I could try this again this week"}]'::jsonb, array['defusion', 'core ACT', 'thoughts']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('ten-year-values-letter', 'Ten-Year Values Letter', 'act'::resource_kind, 'Has a client write a letter from ten years ahead describing a life built on their values.', 'Use it to clarify what actually matters to a client beneath their current worries.', array['Adults']::text[], '25 minutes', 'Ask the client to write as their future self, ten years on, describing an ordinary week lived in line with what matters most to them — not a fantasy of achievement, just the texture of the days. Clients who struggle often default to describing outcomes, a job title, a relationship status, rather than qualities of how they show up; gently redirect toward the latter, since that''s what committed action can actually be built from.', '[{"id": "f0", "type": "textarea", "label": "An ordinary day, ten years from now, if I''m living by what matters to me"}, {"id": "f1", "type": "textarea", "label": "What kind of person am I being in that day"}, {"id": "f2", "type": "textarea", "label": "What''s one thing from that day I could bring into this week"}, {"id": "f3", "type": "textarea", "label": "What gets in the way of that right now"}]'::jsonb, array['values', 'core ACT', 'committed action']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('sky-mind-observing-practice', 'Sky Mind Observing Practice', 'act'::resource_kind, 'Uses the sky and passing weather as a metaphor for the self that notices thoughts and feelings.', 'Use it to build a client''s sense of a stable self that is not the same as their passing thoughts.', array['Adults', 'Teens']::text[], '15 minutes', 'Guide the client to picture themselves as the sky, with each thought, mood, or urge as weather passing through — sometimes calm, sometimes a storm, but the sky itself unchanged underneath. This tends to click for clients who feel defined by whatever mood is loudest that day. Bring it back to a recent difficult moment and ask what stayed constant while the weather in it was rough.', '[{"id": "f0", "type": "textarea", "label": "A recent difficult moment and what the ''weather'' was"}, {"id": "f1", "type": "textarea", "label": "What stayed the same underneath that weather"}, {"id": "f2", "type": "textarea", "label": "A thought I''ve been treating as permanent that might just be passing"}, {"id": "f3", "type": "textarea", "label": "What I notice trying this practice"}]'::jsonb, array['self-as-context', 'core ACT', 'mindfulness']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('willingness-ladder', 'Willingness Ladder', 'act'::resource_kind, 'Ranks situations by how willing a client is to feel discomfort while still moving toward what matters.', 'Use it to build willingness gradually rather than asking for it all at once.', array['Adults', 'Teens']::text[], '20 minutes', 'Unlike a hierarchy built around reducing distress, this ladder is ranked by willingness — how much discomfort the client is prepared to carry while still taking a values-aligned step. Start low enough that the first rung feels genuinely doable this week, and debrief every attempt by asking what the client did while feeling the discomfort, not whether the discomfort went away.', '[{"id": "f0", "type": "textarea", "label": "The value this ladder is in service of"}, {"id": "f1", "type": "textarea", "label": "A step I''m willing to take even with some discomfort (lowest rung)"}, {"id": "f2", "type": "textarea", "label": "A step further up the ladder"}, {"id": "f3", "type": "textarea", "label": "The top rung, whether or not I''m ready for it yet"}, {"id": "f4", "type": "textarea", "label": "What I noticed after trying the lowest rung"}]'::jsonb, array['willingness', 'values', 'committed action']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('committed-action-contract', 'Committed Action Contract', 'act'::resource_kind, 'A short written agreement a client makes with themselves to take one values-aligned action.', 'Use it to turn a values discussion into a specific, dated commitment the client can keep or revisit.', array['Adults']::text[], '15 minutes', 'Keep the action small enough to actually happen this week and tie it explicitly back to a value named earlier in the session, not to an outcome the client can''t control. When a client doesn''t follow through, treat the contract as information about the size of the step rather than a failure, and rewrite it smaller together before ending the session.', '[{"id": "f0", "type": "textarea", "label": "The value behind this action"}, {"id": "f1", "type": "textarea", "label": "The specific action I''m committing to"}, {"id": "f2", "type": "textarea", "label": "By when"}, {"id": "f3", "type": "textarea", "label": "What might get in the way"}, {"id": "f4", "type": "textarea", "label": "How I''ll handle that if it happens"}, {"id": "f5", "type": "textarea", "label": "My signature and today''s date"}]'::jsonb, array['committed action', 'values', 'core ACT']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('nonjudgmental-stance-practice', 'Nonjudgmental Stance Practice', 'dbt'::resource_kind, 'Has a client rewrite a judgmental thought about themselves or others as a plain description.', 'Use it to build the habit of describing events without automatically evaluating them.', array['Adults', 'Teens']::text[], '15 minutes', 'Judgments tend to escalate emotion by adding a verdict on top of a fact, so this practice asks the client to catch a judgment and translate it into what actually happened, with no good, bad, should, or shouldn''t attached. This is harder than it sounds and clients often need a few tries per sentence — that struggle is the skill being built, not a sign it isn''t working.', '[{"id": "f0", "type": "textarea", "label": "A judgmental thought I had recently, exactly as I thought it"}, {"id": "f1", "type": "textarea", "label": "The plain facts underneath it, with no verdict attached"}, {"id": "f2", "type": "textarea", "label": "How my body felt saying the judgment"}, {"id": "f3", "type": "textarea", "label": "How my body felt saying the plain description"}]'::jsonb, array['mindfulness', 'core DBT', 'self-talk']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('what-skills-practice-card', 'What Skills Practice Card', 'dbt'::resource_kind, 'Walks a client through observing, describing, then participating in a moment as it happens.', 'Use it to practice the DBT ''what'' skills as a sequence, not just as ideas.', array['Adults', 'Teens']::text[], '10 minutes', 'Have the client pause during an ordinary moment — a meal, a walk, a conversation — and move through the three skills in order: notice what''s here without words, then put words to it, then step fully into doing it. Most clients skip straight to participating out of habit, so the card works best used in short, deliberate bursts rather than as a running commentary on the whole day.', '[{"id": "f0", "type": "textarea", "label": "The moment I practiced with"}, {"id": "f1", "type": "textarea", "label": "What I observed, before I put words to it"}, {"id": "f2", "type": "textarea", "label": "How I described it"}, {"id": "f3", "type": "textarea", "label": "What it was like to then just participate"}]'::jsonb, array['mindfulness', 'core DBT', 'skills']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('mastery-moment-planner', 'Mastery Moment Planner', 'dbt'::resource_kind, 'Schedules one activity a client can do well as a planned confidence and mood boost.', 'Use it to build a client''s sense of competence on purpose, ahead of a hard stretch.', array['Adults', 'Teens']::text[], '10 minutes', 'The activity needs to be slightly challenging but realistically achievable this week — too easy and it does nothing for confidence, too hard and a client already running low on mood will avoid it. Schedule it like an appointment rather than leaving it to motivation, and check afterward what doing it well actually felt like in the body, not just whether it got done.', '[{"id": "f0", "type": "textarea", "label": "An activity I can reliably do well, even if small"}, {"id": "f1", "type": "textarea", "label": "When this week I''ll do it"}, {"id": "f2", "type": "textarea", "label": "What might get in the way"}, {"id": "f3", "type": "textarea", "label": "How it felt afterward"}]'::jsonb, array['core DBT', 'confidence', 'planning']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('turning-toward-acceptance-log', 'Turning Toward Acceptance Log', 'dbt'::resource_kind, 'Logs the repeated choice to turn toward acceptance of something a client cannot change.', 'Use it to show a client that acceptance is a decision made again and again, not one event.', array['Adults']::text[], '10 minutes', 'Turning the mind is not the same as being at peace with something — it''s the moment of choosing, again, to stop fighting a fact that won''t change right now. Clients often expect one big turn to be enough and get discouraged when the resistance comes back an hour later; this log makes the repetition visible and normal instead of a sign the skill isn''t working.', '[{"id": "f0", "type": "textarea", "label": "The fact I keep resisting"}, {"id": "f1", "type": "textarea", "label": "A moment today I turned my mind toward accepting it"}, {"id": "f2", "type": "textarea", "label": "What pulled me back toward fighting it"}, {"id": "f3", "type": "textarea", "label": "How many times I noticed myself turning today"}]'::jsonb, array['radical acceptance', 'core DBT', 'willingness']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-current-emotion-practice', 'Mindfulness of Current Emotion Practice', 'dbt'::resource_kind, 'Has a client observe a strong emotion moving through them without pushing it away or feeding it.', 'Use it to build tolerance for a feeling''s rise and fall without acting on it right away.', array['Adults', 'Teens']::text[], '10 minutes', 'Ask the client to notice where the emotion sits in the body, name it, and watch it rise and change without trying to fix, judge, or extend it — much like watching a wave rather than surfing or fighting it. This is best introduced with a moderate emotion first, not the client''s most intense one, so they can build the skill before testing it under real pressure.', '[{"id": "f0", "type": "textarea", "label": "The emotion I practiced with"}, {"id": "f1", "type": "textarea", "label": "Where I felt it in my body"}, {"id": "f2", "type": "textarea", "label": "What I noticed as it changed"}, {"id": "f3", "type": "textarea", "label": "Whether I acted on it or just watched it"}]'::jsonb, array['emotion regulation', 'core DBT', 'mindfulness']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('partner-boundary-negotiation-sheet', 'Partner Boundary Negotiation Sheet', 'couples'::resource_kind, 'Has each partner name a boundary they need and negotiate one both can actually keep.', 'Use it to turn a vague complaint about overstepping into a specific, agreed boundary.', array['Couples']::text[], '30 minutes', 'Have each partner fill out their side alone first, since boundaries proposed in the moment tend to be reactions to the last conflict rather than what''s actually needed. In session, look for the version each partner can actually sustain, not the most generous-sounding one — a boundary that gets broken in a week does more damage than a smaller one that holds.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a boundary I need right now"}, {"id": "f1", "type": "textarea", "label": "Partner A: why this one, specifically"}, {"id": "f2", "type": "textarea", "label": "Partner B: a boundary I need right now"}, {"id": "f3", "type": "textarea", "label": "Partner B: why this one, specifically"}, {"id": "f4", "type": "textarea", "label": "What we agreed to try"}, {"id": "f5", "type": "textarea", "label": "How we''ll check back in on it"}]'::jsonb, array['boundaries', 'communication', 'relationships']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('partner-decision-matrix', 'Partner Decision Matrix', 'couples'::resource_kind, 'Lays out both partners'' ratings of shared options side by side before a joint decision.', 'Use it to make a couple''s disagreement about a decision specific instead of circular.', array['Couples']::text[], '25 minutes', 'Works best for a decision with a real deadline — a move, a schedule change, a purchase — rather than an open-ended values debate. Each partner rates every option alone first so the ratings aren''t shaped by the other''s reaction in the room, then compare where they land closest together and where the real gap is, which is usually smaller than the argument made it feel.', '[{"id": "f0", "type": "textarea", "label": "The decision we''re facing"}, {"id": "f1", "type": "textarea", "label": "Options we''re actually considering"}, {"id": "f2", "type": "textarea", "label": "Partner A: rating and reasoning for each option"}, {"id": "f3", "type": "textarea", "label": "Partner B: rating and reasoning for each option"}, {"id": "f4", "type": "textarea", "label": "Where we already agree"}, {"id": "f5", "type": "textarea", "label": "The real gap, stated plainly"}]'::jsonb, array['decisions', 'communication', 'relationships']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('shared-life-transition-map', 'Shared Life Transition Map', 'couples'::resource_kind, 'Maps what each partner expects to gain and lose as a couple moves through a shared change.', 'Use it to surface mismatched expectations about a transition before they turn into conflict.', array['Couples']::text[], '25 minutes', 'Any major shared change — a move, a career switch, an aging parent moving in, an empty nest — carries a private list of hopes and losses each partner may not have said out loud. Have both fill this in separately, then read each other''s answers before discussing; the gap between what one partner assumed the other felt and what they actually wrote is usually where the real conversation starts.', '[{"id": "f0", "type": "textarea", "label": "The transition we''re facing"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I''m hoping for in this"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I''m afraid of losing"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I''m hoping for in this"}, {"id": "f4", "type": "textarea", "label": "Partner B: what I''m afraid of losing"}, {"id": "f5", "type": "textarea", "label": "One thing we can do to support each other through it"}]'::jsonb, array['transitions', 'communication', 'relationships']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('partner-confidence-mirror', 'Partner Confidence Mirror', 'couples'::resource_kind, 'Has each partner name something they''re proud of and hear it reflected back by the other.', 'Use it to build a couple''s habit of noticing and reinforcing each other''s strengths.', array['Couples']::text[], '15 minutes', 'This is a short, structured exchange, not a general compliment session — each partner names one specific thing they did recently that they''re quietly proud of, and the other partner reflects it back in their own words before adding anything of their own. Couples under strain often stop noticing each other''s wins at all, and this rebuilds that muscle in a low-stakes, repeatable way.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something I did recently that I''m proud of"}, {"id": "f1", "type": "textarea", "label": "Partner B: reflecting that back in your own words"}, {"id": "f2", "type": "textarea", "label": "Partner B: something I did recently that I''m proud of"}, {"id": "f3", "type": "textarea", "label": "Partner A: reflecting that back in your own words"}, {"id": "f4", "type": "textarea", "label": "What it was like to hear this from each other"}]'::jsonb, array['confidence', 'communication', 'relationships']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('habit-change-support-agreement', 'Habit Change Support Agreement', 'couples'::resource_kind, 'Sets out exactly how a partner can support a habit change without nagging or policing it.', 'Use it to replace well-meant nagging with support the changing partner actually asked for.', array['Couples']::text[], '20 minutes', 'The partner making the change should write the first two fields alone, since support that hasn''t been requested tends to land as pressure no matter how well intended. Be specific about what to say and when — ''remind me'' and ''don''t remind me'' both need exact wording, or the couple will fall back into the same pattern within a week.', '[{"id": "f0", "type": "textarea", "label": "The habit I''m working on changing"}, {"id": "f1", "type": "textarea", "label": "Support I''m actually asking for"}, {"id": "f2", "type": "textarea", "label": "Support I do NOT want, even if well meant"}, {"id": "f3", "type": "textarea", "label": "Partner: what I heard being asked for"}, {"id": "f4", "type": "textarea", "label": "How we''ll check in on whether this is working"}]'::jsonb, array['habits', 'communication', 'relationships']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('friendship-recipe-craft', 'Friendship Recipe Craft', 'kids'::resource_kind, 'A child writes and decorates a recipe card for being a good friend.', 'Use it to make abstract friendship skills concrete and easy for a child to picture and reuse.', array['Children']::text[], '20 minutes', 'Give the child a blank recipe card and ask what ''ingredients'' go into being a good friend — sharing, listening, saying sorry — and let them decorate it however they like. Younger children often name actions rather than qualities, which is fine and actually more usable. Send the card home and ask the caregiver to reference it by name when they catch the child using one of its ingredients that week.', '[{"id": "f0", "type": "textarea", "label": "Ingredients for being a good friend"}, {"id": "f1", "type": "textarea", "label": "How much of each one (a little or a lot)"}, {"id": "f2", "type": "textarea", "label": "A time I already used one of these ingredients"}, {"id": "f3", "type": "textarea", "label": "One I want to practice more"}]'::jsonb, array['social skills', 'family', 'play']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('confidence-cape-craft', 'Confidence Cape Craft', 'kids'::resource_kind, 'A child decorates a paper cape listing things that make them feel strong and capable.', 'Use it to give a child a concrete object to picture when a hard moment calls for confidence.', array['Children']::text[], '25 minutes', 'Cut a simple cape shape from paper and have the child decorate it with drawings or words for things they''ve done that took courage or skill, however small. Keep the caregiver in the room to help remember real moments the child might not think to name themselves. Hang the cape somewhere visible at home and have the caregiver mention it by name before something the child is nervous about.', '[{"id": "f0", "type": "textarea", "label": "Things I''ve done that took courage or skill"}, {"id": "f1", "type": "textarea", "label": "What my cape looks like"}, {"id": "f2", "type": "textarea", "label": "When I might wear my cape (for real or in my head)"}, {"id": "f3", "type": "textarea", "label": "Caregiver: a moment I saw that I''ll add to the list"}]'::jsonb, array['confidence', 'strengths', 'family']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('habit-tracker-caterpillar', 'Habit Tracker Caterpillar', 'kids'::resource_kind, 'A child colors in one segment of a paper caterpillar for each day they complete a target habit.', 'Use it to make daily habit follow-through visible and rewarding for a child.', array['Children']::text[], '10 minutes daily for two weeks', 'Draw or print a caterpillar with as many segments as days in the plan, and pick one specific, observable habit to track — brushing teeth, packing a bag, a chore — rather than several at once. The caregiver colors in a segment with the child each day it happens, out loud and without lecturing on the days it doesn''t, since the visible chain is doing the motivating work here.', '[{"id": "f0", "type": "textarea", "label": "The one habit we''re tracking"}, {"id": "f1", "type": "textarea", "label": "What the caterpillar looks like so far"}, {"id": "f2", "type": "textarea", "label": "A day it was hard to do the habit, and what happened"}, {"id": "f3", "type": "textarea", "label": "Caregiver: how I''ll celebrate a full caterpillar"}]'::jsonb, array['habits', 'family', 'play']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('decision-wheel-spinner-craft', 'Decision Wheel Spinner Craft', 'kids'::resource_kind, 'A child builds a spinnable paper wheel of calming choices to use when they feel stuck.', 'Use it to give a child a fun, physical way to pick a coping choice instead of freezing or arguing.', array['Children']::text[], '20 minutes', 'Have the child draw and decorate several choices around a paper circle — a drink of water, ten jumping jacks, squeezing a pillow, asking for a hug — then attach a spinnable arrow with a brass fastener. The caregiver keeps the wheel somewhere accessible and offers a spin as a first step at the very start of a hard moment, before things escalate, rather than as a punishment afterward.', '[{"id": "f0", "type": "textarea", "label": "Choices I put on my wheel"}, {"id": "f1", "type": "textarea", "label": "Which one I decorated the most"}, {"id": "f2", "type": "textarea", "label": "A time I used my wheel"}, {"id": "f3", "type": "textarea", "label": "Caregiver: when I''ll offer the wheel next time"}]'::jsonb, array['habits', 'play', 'self-soothing']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('family-meeting-talking-stick-craft', 'Family Meeting Talking Stick Craft', 'kids'::resource_kind, 'A child decorates a talking stick the family passes around during a weekly family meeting.', 'Use it to teach a child turn-taking and listening through a hands-on family routine.', array['Children']::text[], '20 minutes to make, then weekly', 'Any sturdy stick, spoon, or tube works as the base — the decorating is what makes it the child''s. Explain the one rule: whoever holds it talks, everyone else listens, then it passes on. Coach the caregiver to run a short weekly family meeting where each person gets a turn with the stick to share one good thing and one thing they''d like to change, keeping it brief enough that younger children stay engaged.', '[{"id": "f0", "type": "textarea", "label": "What I decorated my talking stick with"}, {"id": "f1", "type": "textarea", "label": "One good thing I said at our meeting"}, {"id": "f2", "type": "textarea", "label": "One thing I asked to change"}, {"id": "f3", "type": "textarea", "label": "Caregiver: when our next family meeting will be"}]'::jsonb, array['family', 'communication', 'routines']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('values-charades', 'Values Charades', 'game'::resource_kind, 'Players act out a value word without speaking while the group guesses which one it is.', 'Use it to make abstract values concrete and get a group talking about why each one matters.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Write values like honesty, courage, or connection on separate cards and have players draw one at a time to act out silently while the group guesses. Once a value is guessed, spend a minute asking who in the group already lives that value in some way and how. The guessing is just the warm-up; the debrief about real examples is where the game earns its place in session.', '[{"id": "f0", "type": "textarea", "label": "Values we used"}, {"id": "f1", "type": "textarea", "label": "The hardest one to act out"}, {"id": "f2", "type": "textarea", "label": "A value I guessed that surprised me"}, {"id": "f3", "type": "textarea", "label": "A value from the game I want more of in my own life"}]'::jsonb, array['values', 'group', 'play']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('assertive-comeback-relay', 'Assertive Comeback Relay', 'game'::resource_kind, 'Teams race to respond assertively to scripted pushy lines, scoring points for tone as well as words.', 'Use it to rehearse assertive responses under mild pressure before they''re needed for real.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Prepare a stack of pushy or guilt-tripping lines a player might hear from a friend, boss, or family member. One player reads a line, the next in line has ten seconds to respond assertively — not aggressively, not passively — before the group scores it and the relay moves on. The time pressure is deliberate: real pushback rarely comes with time to plan the perfect line.', '[{"id": "f0", "type": "textarea", "label": "Lines we used"}, {"id": "f1", "type": "textarea", "label": "A response the group scored highest"}, {"id": "f2", "type": "textarea", "label": "A response that tipped into aggressive or passive, and why"}, {"id": "f3", "type": "textarea", "label": "A line I want to practice more on my own"}]'::jsonb, array['assertiveness', 'group', 'play']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('habit-tracker-race-game', 'Habit Tracker Race Game', 'game'::resource_kind, 'Players move a token forward on a shared board for each day they kept a target habit.', 'Use it to make weekly habit follow-through visible and a little competitive within a group.', array['Teens', 'Adults', 'Groups']::text[], '10 minutes at the start of each session', 'Draw a simple path board with a few bonus and setback spaces scattered along it. Each player names one habit at the start of the week and moves their token forward one space per day it happened, landing on bonus or setback spaces at random. The debrief matters more than the race: ask what helped on the days a player moved forward and what happened on the days they didn''t.', '[{"id": "f0", "type": "textarea", "label": "The habit I''m tracking this week"}, {"id": "f1", "type": "textarea", "label": "Where my token landed by the end"}, {"id": "f2", "type": "textarea", "label": "A bonus or setback space that fit something real that happened"}, {"id": "f3", "type": "textarea", "label": "What helped me move forward this week"}]'::jsonb, array['habits', 'group', 'play']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('the-decision-dice-game', 'The Decision Dice Game', 'game'::resource_kind, 'A die with six decision-making steps that players roll before working through a real choice.', 'Use it to give a group a repeatable structure for talking through a decision out loud.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Label the six sides of a blank die with steps such as pros, cons, values check, gut check, ask someone, sleep on it. A player names a real decision they''re facing, then rolls the die and works through whatever step comes up before rolling again. Rolling the steps out of the usual order tends to surface angles a straight list would have skipped.', '[{"id": "f0", "type": "textarea", "label": "The decision I brought to the game"}, {"id": "f1", "type": "textarea", "label": "The steps I rolled, in order"}, {"id": "f2", "type": "textarea", "label": "The step that gave me the most new information"}, {"id": "f3", "type": "textarea", "label": "Where I landed after playing"}]'::jsonb, array['decisions', 'group', 'play']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('friendship-skills-scavenger-hunt', 'Friendship Skills Scavenger Hunt', 'game'::resource_kind, 'Players complete a list of small friendship actions during the week and report back at the next meeting.', 'Use it to turn friendship skills into small, trackable actions instead of vague advice.', array['Teens', 'Children', 'Groups']::text[], 'One week', 'Give each player the same short list of friendship actions to look for chances to do that week — compliment someone, invite someone to join in, check in with someone having a hard day. At the next session, go around and have each player report which ones they managed and how it went, treating a missed item as information about what''s hard rather than a failure to note.', '[{"id": "f0", "type": "textarea", "label": "Actions on my list"}, {"id": "f1", "type": "textarea", "label": "Which ones I managed this week"}, {"id": "f2", "type": "textarea", "label": "What happened when I tried one"}, {"id": "f3", "type": "textarea", "label": "One I want to try again"}]'::jsonb, array['social skills', 'group', 'play']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('five-minute-start-rule-tracker', 'Five-Minute Start Rule Tracker', 'worksheet'::resource_kind, 'Tracks whether committing to just five minutes on a delayed task actually got it started.', 'Use it to test whether lowering the bar to start is enough to break a pattern of delay.', array['Adults', 'Teens']::text[], 'One week', 'The rule is simple: commit to five minutes only, with full permission to stop after that. Most of the value here is in the data, not the rule itself — some clients find they keep going past five minutes almost every time, others find they genuinely stop, and that''s useful too, since it means the task itself needs breaking down further, not just an easier entry point.', '[{"id": "f0", "type": "textarea", "label": "The task I''m applying this to"}, {"id": "f1", "type": "textarea", "label": "Day 1: did I start? What happened after five minutes?"}, {"id": "f2", "type": "textarea", "label": "Day 2: did I start? What happened after five minutes?"}, {"id": "f3", "type": "textarea", "label": "Day 3: did I start? What happened after five minutes?"}, {"id": "f4", "type": "textarea", "label": "What this tells me about this particular task"}]'::jsonb, array['procrastination', 'habits', 'self-monitoring']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('weekly-balance-check-in-worksheet', 'Weekly Balance Check-In Worksheet', 'worksheet'::resource_kind, 'Has a client rate how much time and energy went to work, rest, people, and health this week.', 'Use it to make an overloaded week visible before it turns into burnout.', array['Adults']::text[], '15 minutes', 'Have the client rate the past week, not an ideal week, across a handful of life domains, then circle the one that got the least attention and wasn''t supposed to. This works well as a recurring check-in rather than a one-time exercise, since the pattern across several weeks usually says more than any single week does on its own.', '[{"id": "f0", "type": "textarea", "label": "Work or responsibilities: how much time and energy this week"}, {"id": "f1", "type": "textarea", "label": "Rest and downtime: how much time and energy this week"}, {"id": "f2", "type": "textarea", "label": "People who matter to me: how much time and energy this week"}, {"id": "f3", "type": "textarea", "label": "My own health: how much time and energy this week"}, {"id": "f4", "type": "textarea", "label": "The one that got less than it needed"}, {"id": "f5", "type": "textarea", "label": "One small change for next week"}]'::jsonb, array['work', 'burnout', 'planning']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('compassionate-pause-card', 'Compassionate Pause Card', 'worksheet'::resource_kind, 'A short three-step script a client can use in the moment when they''re being hard on themselves.', 'Use it to give a client a fast, repeatable alternative to self-criticism in a difficult moment.', array['Adults', 'Teens']::text[], 'Five minutes', 'The three steps are short on purpose so a client can actually use them mid-moment rather than only later in reflection: naming that this is a hard moment, remembering that struggling is something everyone goes through, and offering themselves a kind phrase they choose ahead of time. Have the client write their own phrase in session, since a phrase supplied by someone else rarely feels believable when it''s needed.', '[{"id": "f0", "type": "textarea", "label": "A hard moment I could use this for"}, {"id": "f1", "type": "textarea", "label": "Step 1: naming it (''this is a hard moment'')"}, {"id": "f2", "type": "textarea", "label": "Step 2: remembering I''m not the only one (''struggling is part of being human'')"}, {"id": "f3", "type": "textarea", "label": "Step 3: my own kind phrase to offer myself"}]'::jsonb, array['self-compassion', 'self-soothing', 'self-talk']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('gratitude-letter-worksheet', 'Gratitude Letter Worksheet', 'worksheet'::resource_kind, 'Guides a client through writing a specific letter of thanks to someone who mattered to them.', 'Use it to build gratitude through one detailed act rather than a running list.', array['Adults', 'Teens']::text[], '25 minutes', 'Unlike a running gratitude list, this asks for one specific person and one specific reason, written as an actual letter. Encourage detail over generality — what they did, when, and how it affected the client specifically — since vague thanks tends to feel flat to write and to read. Whether the client ever sends it is optional; the writing itself is where most of the benefit shows up.', '[{"id": "f0", "type": "textarea", "label": "Who this letter is to"}, {"id": "f1", "type": "textarea", "label": "What they did that mattered"}, {"id": "f2", "type": "textarea", "label": "How it affected me at the time"}, {"id": "f3", "type": "textarea", "label": "How it still affects me now"}, {"id": "f4", "type": "textarea", "label": "The letter, in my own words"}, {"id": "f5", "type": "textarea", "label": "Whether I plan to send it"}]'::jsonb, array['gratitude', 'relationships', 'appreciation']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('decision-fatigue-reset-plan', 'Decision Fatigue Reset Plan', 'worksheet'::resource_kind, 'Identifies small daily decisions a client can automate or eliminate to save energy for bigger ones.', 'Use it to free up a client''s decision-making energy for the choices that actually matter to them.', array['Adults']::text[], '20 minutes', 'Have the client list the small decisions that repeat every day — what to wear, what to eat, when to check messages — and sort them into ones worth automating (same choice every time) versus ones worth eliminating outright. This tends to land well with clients who describe feeling drained by the end of an ordinary day with no single obvious cause; the fatigue is often the sum of many small, unnecessary decisions rather than one big one.', '[{"id": "f0", "type": "textarea", "label": "Small decisions that repeat every day for me"}, {"id": "f1", "type": "textarea", "label": "Ones I could automate with a standing default"}, {"id": "f2", "type": "textarea", "label": "Ones I could eliminate outright"}, {"id": "f3", "type": "textarea", "label": "What I''ll do with the energy this frees up"}]'::jsonb, array['decisions', 'burnout', 'habits']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('hyperarousal-interpretation-record', 'Hyperarousal Interpretation Record', 'cbt'::resource_kind, 'A thought record that reframes a racing heart or jumpiness as an old alarm, not present danger.', 'Use it to help clients separate a body''s alarm response from an actual present-moment threat.', array['Adults', 'Teens']::text[], '20 minutes', 'Run this once grounding skills are already in place, since it asks a client to look closely at body sensations that can themselves feel activating. The work is reinterpretation, not exposure: a sensation gets relabeled as a leftover signal from the body''s protective system rather than evidence of current danger. Keep the focus on right now, never on what happened, and pause if a client''s arousal climbs instead of settling.', '[{"id": "f0", "type": "textarea", "label": "A body sensation I noticed (racing heart, tight chest, jumpiness)"}, {"id": "f1", "type": "textarea", "label": "What my mind says this sensation means about right now"}, {"id": "f2", "type": "textarea", "label": "Evidence this is my body''s alarm system rather than a present threat"}, {"id": "f3", "type": "textarea", "label": "One fact about my current surroundings that tells me I am safe enough right now"}, {"id": "f4", "type": "textarea", "label": "A calmer, more accurate way to describe this sensation to myself"}]'::jsonb, array['PTSD and trauma', 'hyperarousal', 'thought record']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('anchor-and-choose-practice', 'Anchor and Choose Practice', 'act'::resource_kind, 'A brief practice pairing a grounding anchor with one small, values-based action after a spike.', 'Use it to help clients move from a flooded moment back into one small, values-aligned step.', array['Adults', 'Teens']::text[], '10 minutes', 'Use this right after a spike in distress has already started to ease, not during the worst of it. The two moves matter in order: ground first, then choose, since asking a flooded client to act on values before they are anchored usually fails. Coach clients toward genuinely small actions, since an ambitious choice can undo the settling that grounding just produced.', '[{"id": "f0", "type": "textarea", "label": "What I noticed in my body that told me my alarm had switched on"}, {"id": "f1", "type": "textarea", "label": "The grounding step I used to come back into the room"}, {"id": "f2", "type": "textarea", "label": "Something that matters to me that I can act on right now, even in a small way"}, {"id": "f3", "type": "textarea", "label": "The one small action I will take"}, {"id": "f4", "type": "textarea", "label": "How steady I feel now, 0 to 10"}]'::jsonb, array['PTSD and trauma', 'grounding', 'values']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('flashback-recovery-roles-plan', 'Flashback Recovery Roles Plan', 'couples'::resource_kind, 'A plan both partners complete for what helps right after a flashback or dissociative moment.', 'Use it to give partners a rehearsed, agreed script instead of improvising in a hard moment.', array['Couples']::text[], '25 minutes', 'Complete this together while both partners are calm and settled, then revisit it after any real moment to fine-tune it. Keep every prompt about present-moment needs and helpful responses, never about what happened to bring on the flashback, since that detail is not required for either partner''s part of this plan. The code word in the last prompt is often what partners use most, since it removes the pressure to explain anything in the moment itself.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what it can look like when I''m having a flashback or feel unsafe in the moment"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I need Partner B to do right when that happens"}, {"id": "f2", "type": "textarea", "label": "Partner A: what Partner B should not do, even if well-meaning"}, {"id": "f3", "type": "textarea", "label": "Partner B: what helps me know whether you need support or space right now"}, {"id": "f4", "type": "textarea", "label": "Both: a code word or signal we''ll use so words aren''t needed in the moment"}, {"id": "f5", "type": "textarea", "label": "Both: what we''ll do together once the moment has passed"}]'::jsonb, array['PTSD and trauma', 'support', 'communication']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('calm-places-passport-craft', 'Calm Places Passport Craft', 'kids'::resource_kind, 'A decorated passport-style booklet of places and objects that help a child''s body feel calm now.', 'Use it to build a ready list of present-moment safe places instead of talking through what happened.', array['Children']::text[], '30 minutes', 'This stays entirely present-focused: a child draws or decorates calm places and comforting objects, never the event itself, so redirect gently back to the here-and-now if a child starts to narrate details. The caregiver''s page turns the passport into a shared plan for actually revisiting these places together during the week. As with any safety-related work with a child, if a child discloses abuse or harm at any point, follow your mandated reporting duties right away.', '[{"id": "f0", "type": "textarea", "label": "Decorate the cover of my Calm Places Passport"}, {"id": "f1", "type": "textarea", "label": "A place at home where my body feels calm — draw it or tell about it"}, {"id": "f2", "type": "textarea", "label": "A place away from home where I feel calm"}, {"id": "f3", "type": "textarea", "label": "Something I can hold, look at, or listen to that helps me feel calm"}, {"id": "f4", "type": "textarea", "label": "A grown-up''s page: how we''ll practice visiting a calm place together this week"}]'::jsonb, array['PTSD and trauma', 'grounding', 'children']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('body-alarm-and-grounding-match', 'Body Alarm and Grounding Match', 'game'::resource_kind, 'A card-matching game pairing body alarm signals with a grounding skill that answers each one.', 'Use it to rehearse fast recognition of alarm signals and the grounding response that fits them.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Shuffle two piles, one of body-alarm cards and one of grounding-skill cards. Each turn, a player draws one card from each pile and argues whether it''s a good match, and the group votes on whether the pairing works. Deliberate mismatches often generate the best discussion, so let a player defend an odd pairing before moving on. Debrief on which grounding skill each player would actually reach for first outside of the room.', '[{"id": "f0", "type": "textarea", "label": "Body alarm cards we used"}, {"id": "f1", "type": "textarea", "label": "Grounding skill cards we used"}, {"id": "f2", "type": "textarea", "label": "Our best match this round, and why"}, {"id": "f3", "type": "textarea", "label": "A pairing that surprised us"}, {"id": "f4", "type": "textarea", "label": "The grounding skill I''d reach for first outside of here"}]'::jsonb, array['PTSD and trauma', 'grounding', 'play']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('nighttime-anxiety-wind-down-log', 'Nighttime Anxiety Wind-Down Log', 'worksheet'::resource_kind, 'A nightly log that pairs an anxious bedtime thought with one short wind-down step.', 'Use it to separate lying-awake worry from the body''s need to wind down before sleep.', array['Adults', 'Teens']::text[], 'Five minutes nightly for two weeks', 'This is narrower than a full sleep hygiene review: it targets the specific moment anxiety shows up at bedtime and gives the client one alternative to problem-solving under the covers. Watch for clients using the log itself to keep planning or ruminating rather than noticing a pattern, and steer them back to the single wind-down step. Review the pattern line together after a week or two rather than each night.', '[{"id": "f0", "type": "textarea", "label": "Tonight''s worry, in a few words"}, {"id": "f1", "type": "textarea", "label": "Where I notice it in my body right now"}, {"id": "f2", "type": "textarea", "label": "One wind-down step I''ll do instead of scrolling or planning in bed"}, {"id": "f3", "type": "textarea", "label": "What time I think I actually fell asleep"}, {"id": "f4", "type": "textarea", "label": "One pattern I''m noticing after a few nights"}]'::jsonb, array['anxiety', 'sleep', 'self-monitoring']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('anxious-moment-choice-point', 'Anxious Moment Choice Point', 'act'::resource_kind, 'A choice-point map for an anxious moment, sorting hooked, avoidant moves from values-based ones.', 'Use it to help clients notice the pull toward avoidance and pick one toward move instead.', array['Adults', 'Teens']::text[], '15 minutes', 'Draw the choice point live with the client the first time, since sketching the fork between away moves and toward moves usually lands better than reading it off a sheet. Anxiety-specific away moves tend to be subtle, such as checking, seeking reassurance, or over-preparing, so help clients name the version they actually do rather than a generic one. The toward move at the end should be genuinely small enough to attempt this week.', '[{"id": "f0", "type": "textarea", "label": "The anxious moment: what happened right before anxiety showed up"}, {"id": "f1", "type": "textarea", "label": "The hooked or away moves I''m pulled toward (avoid, escape, check, control)"}, {"id": "f2", "type": "textarea", "label": "What matters to me in this situation"}, {"id": "f3", "type": "textarea", "label": "One unhooking or grounding move I can use right here"}, {"id": "f4", "type": "textarea", "label": "One small toward move I can take next"}]'::jsonb, array['anxiety', 'choice point', 'values']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('dear-man-for-anxious-requests', 'DEAR MAN for Anxious Requests', 'dbt'::resource_kind, 'A DEAR MAN script for making a request or saying no despite anxiety about the reaction.', 'Use it to help clients state a need clearly instead of avoiding the ask altogether.', array['Adults', 'Teens']::text[], '20 minutes', 'This applies the standard DEAR MAN sequence to a specific kind of moment: an ask the client keeps avoiding because anxiety predicts a bad reaction. Have the client script the words out loud in session before trying it for real, since anxious clients tend to soften the Assert line until it no longer functions as a request. The last prompt keeps the anxious prediction visible instead of pretending the ask will feel comfortable.', '[{"id": "f0", "type": "textarea", "label": "The anxious situation where I need to make a request or say no"}, {"id": "f1", "type": "textarea", "label": "Describe: the facts of the situation, without judgment"}, {"id": "f2", "type": "textarea", "label": "Express: how I feel and why this matters to me"}, {"id": "f3", "type": "textarea", "label": "Assert: the specific request or ''no'' I want to state"}, {"id": "f4", "type": "textarea", "label": "Reinforce: what''s in it for the other person if they agree"}, {"id": "f5", "type": "textarea", "label": "The anxious prediction I expect, and my plan to make the ask anyway"}]'::jsonb, array['anxiety', 'DEAR MAN', 'interpersonal effectiveness']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('worry-calming-recipe-card-craft', 'Worry-Calming Recipe Card Craft', 'kids'::resource_kind, 'A decorated recipe card listing a child''s own ingredients for calming their worry.', 'Use it to turn a child''s coping steps into a memorable, personalized recipe they can reuse.', array['Children']::text[], '25 minutes', 'Have the child decorate the card like a real recipe, with a title, a short ingredients list, and simple steps, so the format feels playful rather than clinical. Keep ingredients concrete and physical, such as breathing, a hug, or a specific phrase, rather than abstract advice a child can''t picture using. The caregiver''s line turns this into something usable at home: a cue for catching early worry signs and prompting the recipe before worry builds.', '[{"id": "f0", "type": "textarea", "label": "Decorate the title of my worry-calming recipe"}, {"id": "f1", "type": "textarea", "label": "Ingredient 1: something I do with my body"}, {"id": "f2", "type": "textarea", "label": "Ingredient 2: something I say to myself"}, {"id": "f3", "type": "textarea", "label": "Ingredient 3: someone I can ask for help"}, {"id": "f4", "type": "textarea", "label": "How long my recipe takes and where I can use it"}, {"id": "f5", "type": "textarea", "label": "A grown-up''s note: one early worry sign to watch for and remind me to use my recipe"}]'::jsonb, array['anxiety', 'children', 'coping skills']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('anxiety-signal-charades', 'Anxiety Signal Charades', 'game'::resource_kind, 'A charades game acting out body anxiety signals, then naming a coping skill for each one.', 'Use it to build quick recognition of early body signals and the skills that answer them.', array['Teens', 'Groups', 'Children']::text[], '20 minutes', 'Players take turns drawing a body-signal card, such as a racing heart or shaky hands, and act it out silently while the group guesses. Once guessed, the group names a coping skill that fits that particular signal before moving on. Debrief on which signal was hardest to guess and which signal each player notices earliest in their own body, since that one is worth practicing catching first.', '[{"id": "f0", "type": "textarea", "label": "Body signal cards we acted out"}, {"id": "f1", "type": "textarea", "label": "Coping skill we matched to each signal"}, {"id": "f2", "type": "textarea", "label": "The signal that was easiest to guess, and why"}, {"id": "f3", "type": "textarea", "label": "A body signal I want to notice earlier in real life"}]'::jsonb, array['anxiety', 'body awareness', 'play']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('basic-functioning-check-in', 'Basic Functioning Check-In', 'worksheet'::resource_kind, 'A gentle daily checklist of basic self-care tasks during a depressive stretch.', 'Use it to track daily functioning without judgment when depression flattens routines.', array['Adults']::text[], 'Five minutes daily', 'Use this on stretches when even ordinary tasks feel out of reach. The checklist is deliberately low bar and nonjudgmental: eating something, having water, getting out of bed, and any contact with another person all count as real, whether or not the client thinks they should be harder or easier than they are. Watch for clients using it to grade themselves harshly, and steer the conversation back toward noticing rather than scoring.', '[{"id": "f0", "type": "textarea", "label": "Today, have I eaten something? What?"}, {"id": "f1", "type": "textarea", "label": "Have I had something to drink today?"}, {"id": "f2", "type": "textarea", "label": "Have I gotten out of bed or changed out of pajamas today?"}, {"id": "f3", "type": "textarea", "label": "Have I had contact with another person today, even a text?"}, {"id": "f4", "type": "textarea", "label": "One thing I did today that counts as taking care of myself, however small"}, {"id": "f5", "type": "textarea", "label": "One thing that might make tomorrow slightly easier"}]'::jsonb, array['depression', 'self-monitoring', 'self-compassion']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('depression-maintenance-cycle-map', 'Depression Maintenance Cycle Map', 'cbt'::resource_kind, 'A formulation mapping how low mood, withdrawal, and rumination keep feeding each other.', 'Use it to show clients exactly where one small change could interrupt their own cycle.', array['Adults', 'Teens']::text[], '25 minutes', 'Build this cycle together on paper the way you would a panic or obsession cycle, since seeing the loop drawn out tends to land better than describing it. Most clients can name the withdrawal and the mood drop easily but miss the thought step in between, so slow down there. The real use of the map is the fifth box: picking one point in the loop where a small opposite action is realistic this week, not the whole cycle at once.', '[{"id": "f0", "type": "textarea", "label": "What my mood was like right before this cycle started"}, {"id": "f1", "type": "textarea", "label": "What I pulled back from or stopped doing as a result"}, {"id": "f2", "type": "textarea", "label": "What thoughts showed up once I pulled back"}, {"id": "f3", "type": "textarea", "label": "What happened to my mood after withdrawing further"}, {"id": "f4", "type": "textarea", "label": "Where in this cycle I could insert one small opposite action"}, {"id": "f5", "type": "textarea", "label": "What I will watch for next time this cycle starts"}]'::jsonb, array['depression', 'formulation', 'maintenance cycle']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('depression-crisis-survival-card', 'Depression Crisis Survival Card', 'dbt'::resource_kind, 'A crisis survival card built in session for the hardest moments of a depressive episode.', 'Use it to give clients a rehearsed set of steps for the worst moments, not something to invent then.', array['Adults', 'Teens']::text[], 'Full session', 'Build this together in session rather than sending it home to complete alone, since it is meant for a client''s worst moments and needs to be rehearsed with support present. Walk through every line out loud, including the 988 line, so the card reflects something the client has actually said aloud and can picture using, not a generic list. Revisit and update the card whenever risk comes up again.', '[{"id": "f0", "type": "textarea", "label": "What tells me I am sliding toward crisis (thoughts, urges, or feelings)"}, {"id": "f1", "type": "textarea", "label": "One thing I can do right now to change my body''s state (cold water, brisk movement, paced breathing)"}, {"id": "f2", "type": "textarea", "label": "One way I can distract or self-soothe for the next fifteen minutes"}, {"id": "f3", "type": "textarea", "label": "If thoughts of suicide show up, I will call or text 988 (call or text) and tell my clinician"}, {"id": "f4", "type": "textarea", "label": "Who else I can reach besides my clinician if I need support right now"}, {"id": "f5", "type": "textarea", "label": "What has helped once the worst of a wave has passed before"}]'::jsonb, array['depression', 'crisis', 'distress tolerance']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('depression-household-load-plan', 'Depression Household Load Plan', 'couples'::resource_kind, 'A conversation plan for temporarily reshuffling household tasks during a partner''s depressive episode.', 'Use it to replace guilt or resentment with a clear, time-limited task plan both partners agree to.', array['Couples']::text[], '20 minutes', 'This is a practical task conversation, not an emotional-support script, and it works best alongside whatever else you''re doing for support and connection. Set an explicit end date or check-in point so the arrangement stays time-limited rather than becoming a silent new normal. Watch for the well partner offering to take on everything: naming one small task the depressed partner keeps doing, even if imperfectly, tends to matter more than it looks like it would.', '[{"id": "f0", "type": "textarea", "label": "Partner A: which tasks feel hardest to keep up with right now"}, {"id": "f1", "type": "textarea", "label": "Partner B: which of those tasks I can realistically pick up for now"}, {"id": "f2", "type": "textarea", "label": "Both: tasks we''ll let slide on purpose for now, without guilt"}, {"id": "f3", "type": "textarea", "label": "Both: how long this arrangement will last before we check in again"}, {"id": "f4", "type": "textarea", "label": "Partner B: one way I can help without taking over everything"}, {"id": "f5", "type": "textarea", "label": "Partner A: one small way I can stay involved so it doesn''t feel one-sided"}]'::jsonb, array['depression', 'household', 'support']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('energy-investment-auction', 'Energy Investment Auction', 'game'::resource_kind, 'An auction game where players bid limited energy points on activities worth trying this week.', 'Use it to surface which activities clients would actually choose versus what depression says to skip.', array['Adults', 'Teens', 'Groups']::text[], '25 minutes', 'List ten to twelve activities on the board, mixing mastery and pleasure options, then give each player a fixed number of energy points to bid across a few rounds. Players compete for the activities they actually want to try, which surfaces real preference faster than asking directly usually does. Debrief on what a player was drawn to bid on, what they skipped despite once enjoying it, and which winning bid they''re most likely to actually follow through on this week.', '[{"id": "f0", "type": "textarea", "label": "Activities on our auction list"}, {"id": "f1", "type": "textarea", "label": "What I bid my energy points on, and why"}, {"id": "f2", "type": "textarea", "label": "An activity I almost skipped bidding on, and why I reconsidered"}, {"id": "f3", "type": "textarea", "label": "What I noticed about what I was drawn to versus what I expected"}, {"id": "f4", "type": "textarea", "label": "The activity I''m most likely to actually try this week"}]'::jsonb, array['depression', 'behavioral activation', 'play']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('hyperfocus-exit-plan', 'Hyperfocus Exit Plan', 'worksheet'::resource_kind, 'A worksheet that sets a hard stop and an exit ritual for when hyperfocus swallows the rest of the day.', 'Use it to build an off-ramp so hyperfocus does not quietly cancel the rest of a client''s day.', array['Adults']::text[], '20 minutes', 'Bring this in after a session where the client describes losing hours to a task they didn''t mean to start. The exit ritual works best when it''s absurdly small — a single alarm, one physical cue like standing up — because anything more elaborate gets skipped once focus locks in. Revisit which cues actually got noticed, not which ones sounded good on paper.', '[{"id": "f0", "type": "textarea", "label": "A time I lost track of hours in something I didn''t plan to do"}, {"id": "f1", "type": "textarea", "label": "What pulled me in so completely"}, {"id": "f2", "type": "textarea", "label": "The alarm or cue I will set before I start something absorbing"}, {"id": "f3", "type": "textarea", "label": "One thing I will physically do when the alarm goes off"}, {"id": "f4", "type": "textarea", "label": "Who or what will remind me if I miss the first cue"}, {"id": "f5", "type": "textarea", "label": "What I want to protect time for today"}]'::jsonb, array['ADHD', 'hyperfocus', 'transitions']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('impulse-pause-thought-record', 'Impulse Pause Thought Record', 'cbt'::resource_kind, 'A CBT thought record that captures what ran through a client''s mind the second before an impulsive choice.', 'Use it to slow the gap between urge and action long enough for a thought to be examined.', array['Adults', 'Teens']::text[], '20 minutes', 'Use this right after an impulsive purchase, message, or decision the client regrets, while the sequence is still fresh. The record works because it separates the thought from the action — many clients have never noticed there was a thought at all, only the outcome. Watch for clients who fill in a tidy explanation after the fact; ask what they can remember noticing in the body in that exact second.', '[{"id": "f0", "type": "textarea", "label": "The impulsive choice I made or almost made"}, {"id": "f1", "type": "textarea", "label": "What I was feeling in my body right before"}, {"id": "f2", "type": "textarea", "label": "The thought that was there, even if I only notice it now"}, {"id": "f3", "type": "textarea", "label": "What I told myself that made the action feel okay in the moment"}, {"id": "f4", "type": "textarea", "label": "What was actually true, looking at it now"}, {"id": "f5", "type": "textarea", "label": "One thing I could do in that same second next time"}]'::jsonb, array['ADHD', 'impulsivity', 'thought record']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('boring-task-values-bridge', 'Boring Task Values Bridge', 'act'::resource_kind, 'An ACT exercise that links a tedious, necessary task to a value the client actually cares about.', 'Use it to make willingness to sit with boredom feel purposeful rather than just effortful.', array['Adults', 'Teens']::text[], '15 minutes', 'This is for the paperwork, the inbox, the form — tasks with no built-in interest that ADHD makes almost impossible to start. The bridge only works if the value is genuinely the client''s own, not a should; press past the first answer if it sounds borrowed from a parent or boss. Pair it with a short willingness practice for the boredom itself, since the task will still feel dull even once it''s meaningful.', '[{"id": "f0", "type": "textarea", "label": "The boring task I keep avoiding"}, {"id": "f1", "type": "textarea", "label": "A value this task actually connects to, even loosely"}, {"id": "f2", "type": "textarea", "label": "How doing this task moves me toward that value"}, {"id": "f3", "type": "textarea", "label": "What boredom feels like in my body when I try to start"}, {"id": "f4", "type": "textarea", "label": "Am I willing to feel that, for the next ten minutes, in service of what matters"}]'::jsonb, array['ADHD', 'values', 'willingness']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('executive-function-division-of-labor', 'Executive Function Division of Labor', 'couples'::resource_kind, 'A couples worksheet that divides household tasks by each partner''s actual executive function strengths.', 'Use it to replace resentment over forgotten tasks with a division of labor both partners chose.', array['Couples']::text[], '30 minutes', 'Run this with both partners in the room, and resist letting it turn into a scorecard of who forgets more. One partner typically manages time and initiation more easily; the other may track details or follow through once a task is started. Naming those differences out loud, without judgment, is what lets the couple redesign who owns what instead of relitigating the same missed task every week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks I start easily and follow through on"}, {"id": "f1", "type": "textarea", "label": "Partner A: tasks I consistently forget or put off"}, {"id": "f2", "type": "textarea", "label": "Partner B: tasks I start easily and follow through on"}, {"id": "f3", "type": "textarea", "label": "Partner B: tasks I consistently forget or put off"}, {"id": "f4", "type": "textarea", "label": "A task we will reassign based on what we just named"}, {"id": "f5", "type": "textarea", "label": "How we will remind each other without it turning into nagging"}, {"id": "f6", "type": "textarea", "label": "What we will say to each other when a task still gets missed"}]'::jsonb, array['ADHD', 'couples', 'executive function']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('the-wiggle-break-wheel', 'The Wiggle Break Wheel', 'kids'::resource_kind, 'A spinner wheel of movement breaks that a child decorates and a caregiver uses between tasks.', 'Use it to give a wiggly child a planned, physical outlet instead of a battle over sitting still.', array['Children']::text[], '20 minutes to build, then ongoing', 'Have the child draw, cut out, and color each wedge of movement — ten jumping jacks, an animal walk across the room, three spins in place — themselves, since ownership is what makes them use it later. The caregiver''s job is to spin the wheel and hold the timer at agreed transition points, not to decide when a break is deserved, since that turns it back into a control fight. Keep wedges short enough that the break ends before it becomes the new distraction.', '[{"id": "f0", "type": "textarea", "label": "Movement ideas I want on my wheel"}, {"id": "f1", "type": "textarea", "label": "Draw or decorate each wedge"}, {"id": "f2", "type": "textarea", "label": "When during the day my grown-up will spin it with me"}, {"id": "f3", "type": "textarea", "label": "How I will know when my break is over"}, {"id": "f4", "type": "textarea", "label": "What I do after the break is done"}]'::jsonb, array['ADHD', 'children', 'play']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('high-risk-situation-rehearsal-card', 'High-Risk Situation Rehearsal Card', 'cbt'::resource_kind, 'A card that walks a client through rehearsing a coping response before a known high-risk situation.', 'Use it to have a coping response already rehearsed before urges arrive, not invented under pressure.', array['Adults']::text[], '20 minutes', 'Build this for one specific situation the client has already identified as high-risk — a particular time, place, or person — rather than urges in general. Walk through the scene in detail and have the client say the coping line out loud, since rehearsal that stays silent in their head rarely holds up in the real moment. Revisit and rewrite the card after the situation actually happens, whether it went well or not.', '[{"id": "f0", "type": "textarea", "label": "The specific situation I''m preparing for"}, {"id": "f1", "type": "textarea", "label": "What usually happens right before the urge shows up"}, {"id": "f2", "type": "textarea", "label": "The coping response I will use, in my own words"}, {"id": "f3", "type": "textarea", "label": "What I will do with my hands or body in that moment"}, {"id": "f4", "type": "textarea", "label": "Who I can contact if the urge is stronger than expected"}, {"id": "f5", "type": "textarea", "label": "What I will tell myself I already know how to do"}]'::jsonb, array['addiction', 'urges', 'relapse prevention']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('urge-defusion-card', 'Urge Defusion Card', 'act'::resource_kind, 'An ACT card that helps a client notice an urge as a passing thought rather than an instruction.', 'Use it to create distance between noticing an urge and treating it as something that must be obeyed.', array['Adults', 'Teens']::text[], '10 minutes', 'This is a brief defusion drill, not a distraction technique — the goal is for the client to notice the urge and the story attached to it, not to make the urge disappear. Have them practice saying “I''m having the urge that…” out loud before trying it silently during a real craving. Some clients want to argue with the urge instead of just naming it; gently redirect them back to noticing rather than debating.', '[{"id": "f0", "type": "textarea", "label": "The urge as it actually showed up"}, {"id": "f1", "type": "textarea", "label": "The urge, named as a thought: I''m having the urge that..."}, {"id": "f2", "type": "textarea", "label": "What the urge is trying to convince me will happen if I don''t act"}, {"id": "f3", "type": "textarea", "label": "What I actually value in this moment, urge aside"}, {"id": "f4", "type": "textarea", "label": "What I did instead of obeying the urge"}]'::jsonb, array['addiction', 'urges', 'defusion']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-urges', 'Opposite Action for Urges', 'dbt'::resource_kind, 'A DBT worksheet that has a client identify the action an urge is pushing for, then deliberately do the opposite.', 'Use it to practice acting against an urge''s pull instead of following it automatically.', array['Adults']::text[], '15 minutes', 'This only works when the client can name the urge accurately first, so slow down that step rather than rushing to the opposite action. Opposite action here is not white-knuckling; it''s a specific, planned, different behavior done fully, not halfheartedly. Check in afterward on what happened in the body and mood once the opposite action was completed, since that follow-through is what teaches the nervous system something new.', '[{"id": "f0", "type": "textarea", "label": "The urge and what it wants me to do"}, {"id": "f1", "type": "textarea", "label": "The situation that brought it on"}, {"id": "f2", "type": "textarea", "label": "The opposite action, stated as something concrete I can actually do"}, {"id": "f3", "type": "textarea", "label": "How I will do it fully, not halfway"}, {"id": "f4", "type": "textarea", "label": "What happened in my body and mood after"}]'::jsonb, array['addiction', 'urges', 'opposite action']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('my-circle-of-grown-ups', 'My Circle of Grown-Ups', 'kids'::resource_kind, 'A drawing activity where a child maps the safe grown-ups they can go to when substance use affects their family.', 'Use it to help a child name concrete safe adults and actions, separate from a family member''s substance use.', array['Children']::text[], '25 minutes', 'The child draws themselves in the center and the safe grown-ups in their life around them, adding what each person can help with — a ride, a hug, a place to go. Keep language behavior-focused throughout, talking about someone''s substance use and never a label for that person, and let the caregiver in session, if present, hear the child name what helps without correcting or defending. If the child discloses anything suggesting they are unsafe or unsupervised, pause the activity and follow your mandated reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw yourself in the middle of the circle"}, {"id": "f1", "type": "textarea", "label": "Draw or write the grown-ups who help keep you safe"}, {"id": "f2", "type": "textarea", "label": "What each person can help you with"}, {"id": "f3", "type": "textarea", "label": "A safe place I can go if things feel scary or confusing at home"}, {"id": "f4", "type": "textarea", "label": "One thing I want a grown-up to know about how I''m feeling"}]'::jsonb, array['addiction', 'children', 'support']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('the-craving-clock-game', 'The Craving Clock Game', 'game'::resource_kind, 'A group game where players time how long an imagined urge lasts while using a coping skill, then compare notes.', 'Use it to make the idea concrete that urges rise, peak, and pass if given time.', array['Adults', 'Teens', 'Groups']::text[], '25 minutes', 'Each player draws a situation card describing a common trigger, picks a coping skill card, and the group sets a two-minute timer while that player narrates their imagined intensity out loud, high to low. The debrief is the point: compare how fast intensity dropped across different coping skills and situations, and let the group notice that no one''s urge stayed at a ten for the full two minutes. Keep the tone playful, not testing, or players will perform certainty instead of reporting what they''d actually feel.', '[{"id": "f0", "type": "textarea", "label": "Situation card drawn"}, {"id": "f1", "type": "textarea", "label": "Coping skill card drawn"}, {"id": "f2", "type": "textarea", "label": "Starting intensity, 1 to 10"}, {"id": "f3", "type": "textarea", "label": "Intensity at the end of the timer"}, {"id": "f4", "type": "textarea", "label": "What helped it drop, or what got in the way"}]'::jsonb, array['addiction', 'urges', 'group']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('anger-aftermath-repair-plan', 'Anger Aftermath Repair Plan', 'worksheet'::resource_kind, 'A worksheet completed after an anger episode that plans the repair conversation and what to do differently.', 'Use it to turn the period right after an outburst into a structured repair instead of avoidance.', array['Adults', 'Teens']::text[], '20 minutes', 'Bring this in a session or two after an anger episode the client wants to repair, once they''re regulated enough to look at it without reigniting. Separate the apology from the plan — clients often stop at sorry and skip naming what they''ll actually do differently, which is what the other person usually needs to hear. If the episode involved a partner or family member, consider whether a joint session to deliver the repair together would land better than the client doing it alone.', '[{"id": "f0", "type": "textarea", "label": "What happened, in a few neutral sentences"}, {"id": "f1", "type": "textarea", "label": "What I said or did that I want to repair"}, {"id": "f2", "type": "textarea", "label": "The impact on the other person, as best I can tell"}, {"id": "f3", "type": "textarea", "label": "What I will say when I approach them"}, {"id": "f4", "type": "textarea", "label": "What I will do differently if this situation comes up again"}, {"id": "f5", "type": "textarea", "label": "When I plan to have this conversation"}]'::jsonb, array['anger management', 'repair', 'conflict']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('angry-passengers-on-the-bus', 'Angry Passengers on the Bus', 'act'::resource_kind, 'An ACT exercise using the bus-driver metaphor to practice acting on values while anger rides along.', 'Use it to help a client keep driving toward what matters without letting anger grab the wheel.', array['Adults', 'Teens']::text[], '20 minutes', 'Introduce the metaphor first: the client is the driver, and anger, along with its usual demands to yell, slam, or shut down, is a loud passenger who doesn''t actually hold the wheel. This works best paired with a real recent situation rather than staying abstract, so the client can picture the passenger''s exact voice. Watch for clients who try to argue the passenger into silence; the aim is closer to acknowledging it''s there and continuing to drive.', '[{"id": "f0", "type": "textarea", "label": "A recent situation where angry passengers got loud"}, {"id": "f1", "type": "textarea", "label": "What that passenger was telling me to do"}, {"id": "f2", "type": "textarea", "label": "Where I actually wanted to drive, the value underneath"}, {"id": "f3", "type": "textarea", "label": "What I did instead of handing over the wheel"}, {"id": "f4", "type": "textarea", "label": "What I will say to that passenger next time it gets loud"}]'::jsonb, array['anger management', 'values', 'defusion']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-for-old-anger', 'Radical Acceptance for Old Anger', 'dbt'::resource_kind, 'A DBT worksheet applying radical acceptance to resentment a client has carried for a long time.', 'Use it to loosen the grip of old anger that fighting reality has failed to resolve.', array['Adults']::text[], '25 minutes', 'This is for the anger that''s aged past the original event, when a client is still replaying something months or years old. Distinguish acceptance from approval early, since clients often hear this exercise as being asked to say the situation was fine; it wasn''t, and the worksheet doesn''t ask them to say it was. Expect resistance in the first pass; radical acceptance rarely lands as a single decision, and revisiting this worksheet across sessions is normal.', '[{"id": "f0", "type": "textarea", "label": "The old situation I''m still carrying anger about"}, {"id": "f1", "type": "textarea", "label": "What I keep telling myself should have happened instead"}, {"id": "f2", "type": "textarea", "label": "What is actually true about it now, whether I like it or not"}, {"id": "f3", "type": "textarea", "label": "What fighting this reality has cost me so far"}, {"id": "f4", "type": "textarea", "label": "One sentence of acceptance I''m willing to try, even partly"}, {"id": "f5", "type": "textarea", "label": "What I want to do with my energy instead of replaying this"}]'::jsonb, array['anger management', 'radical acceptance']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('partner-anger-trigger-exchange', 'Partner Anger Trigger Exchange', 'couples'::resource_kind, 'A couples worksheet where each partner names their own anger triggers before conflict, not during it.', 'Use it to give both partners a map of what sets the other off, made in a calm moment.', array['Couples']::text[], '30 minutes', 'Do this on a calm day, never mid-argument — the point is prevention, not a rulebook to weaponize later. Have each partner fill out their own column independently first, then trade and read the other''s out loud, which often surfaces triggers the other partner never realized they were causing. Circle back to this worksheet after real disagreements to check whether a named trigger showed up and whether the requested response actually happened.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what tends to trigger my anger"}, {"id": "f1", "type": "textarea", "label": "Partner A: what helps me when I''m already angry"}, {"id": "f2", "type": "textarea", "label": "Partner A: what makes it worse"}, {"id": "f3", "type": "textarea", "label": "Partner B: what tends to trigger my anger"}, {"id": "f4", "type": "textarea", "label": "Partner B: what helps me when I''m already angry"}, {"id": "f5", "type": "textarea", "label": "Partner B: what makes it worse"}, {"id": "f6", "type": "textarea", "label": "One thing each of us will try differently based on what we just read"}]'::jsonb, array['anger management', 'couples', 'triggers']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('the-anger-scale-guessing-game', 'The Anger Scale Guessing Game', 'game'::resource_kind, 'A group game where players guess each other''s anger rating for a scenario, then debrief the gaps.', 'Use it to show how differently people rate the same situation on an anger scale.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'One player reads a scenario card aloud, everyone privately writes a number from one to ten for how angry they''d feel, then all numbers are revealed at once. The gaps are the whole point: a scenario that lands as a two for one player and an eight for another opens a debrief about why, without anyone being told their number is wrong. Keep score loosely if at all — closeness to the group average is far less interesting than the reasons behind the spread.', '[{"id": "f0", "type": "textarea", "label": "Scenario read aloud"}, {"id": "f1", "type": "textarea", "label": "My anger rating, 1 to 10"}, {"id": "f2", "type": "textarea", "label": "The group''s range of ratings"}, {"id": "f3", "type": "textarea", "label": "What made my number different from someone else''s"}, {"id": "f4", "type": "textarea", "label": "What I noticed about how people size up the same situation"}]'::jsonb, array['anger management', 'group', 'play']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('ocd-theme-inventory', 'OCD Theme Inventory', 'worksheet'::resource_kind, 'A one-page map of which OCD themes show up most for this client right now.', 'Use it to organize scattered obsessions and compulsions into named themes you can track together.', array['Adults', 'Teens']::text[], '20 minutes', 'Many clients name one obsession when several run in parallel, and progress stalls when a theme goes untracked. Have the client list every theme they can identify before ranking them, since the ranking itself often reveals which one is actually driving the most distress. Revisit this sheet every few sessions, since themes shift as compulsions are given up and a new one sometimes moves in to take the vacated space.', '[{"id": "f0", "type": "textarea", "label": "The themes my mind gets stuck on (checking, contamination, symmetry, harm, relationship, right or wrong, other)"}, {"id": "f1", "type": "textarea", "label": "For each theme, the obsession that runs through my head"}, {"id": "f2", "type": "textarea", "label": "For each theme, what I do to get rid of the obsession"}, {"id": "f3", "type": "textarea", "label": "Which theme takes up the most time right now"}, {"id": "f4", "type": "textarea", "label": "Which theme is the easiest one to start working on"}, {"id": "f5", "type": "textarea", "label": "What I notice in common across my themes"}]'::jsonb, array['OCD', 'obsessions', 'compulsions']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('erp-session-log', 'ERP Session Log', 'cbt'::resource_kind, 'A log for recording each exposure and response prevention practice and what happened.', 'Use it to track discomfort ratings and ritual resistance across exposures so progress stays visible.', array['Adults', 'Teens']::text[], '10 minutes after each practice', 'Clients tend to round their peak discomfort rating down once the exposure is over, so ask them to log it in the moment or as close to it as possible rather than from memory afterward. The most useful column is often the last one: a completed exposure with a partial ritual still counts as data, and naming exactly what happened teaches more than a pass or fail mark. Review the trend across entries together rather than judging any single exposure on its own.', '[{"id": "f0", "type": "textarea", "label": "The exposure I practiced"}, {"id": "f1", "type": "textarea", "label": "My discomfort rating right before I started (0-10)"}, {"id": "f2", "type": "textarea", "label": "My discomfort rating at the peak"}, {"id": "f3", "type": "textarea", "label": "My discomfort rating at the end"}, {"id": "f4", "type": "textarea", "label": "Did I complete it without doing the compulsion? What happened instead"}, {"id": "f5", "type": "textarea", "label": "What I noticed about how the urge changed over time"}, {"id": "f6", "type": "textarea", "label": "What I want to try next time"}]'::jsonb, array['OCD', 'exposure', 'response prevention']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('tipp-for-compulsion-urges', 'TIPP for Compulsion Urges', 'dbt'::resource_kind, 'A card that applies the DBT TIPP skills to bring down a compulsion urge fast enough to sit with it.', 'Use it when an urge to ritualize spikes and the client needs a few minutes of relief before choosing not to act on it.', array['Adults', 'Teens']::text[], 'Five minutes', 'TIPP was built to bring down emotional arousal fast, and a compulsion urge behaves the same way physiologically as any other spike in the DBT model. Use this in the middle of a hard moment rather than saving it for session: the point is to buy the client sixty to ninety seconds so the urge has room to fall before they decide whether to ritualize. It works better paired with a plan for what they will do with that window, since dropping the arousal without a next step often just delays the compulsion.', '[{"id": "f0", "type": "textarea", "label": "The urge I''m having right now and how strong it feels (0-10)"}, {"id": "f1", "type": "textarea", "label": "Temperature: cold water on my face or hands, for 30 seconds"}, {"id": "f2", "type": "textarea", "label": "Intense exercise: a minute of jumping jacks or fast stair climbs"}, {"id": "f3", "type": "textarea", "label": "Paced breathing: longer exhale than inhale, for one minute"}, {"id": "f4", "type": "textarea", "label": "Paired muscle relaxation: tense and release, one minute"}, {"id": "f5", "type": "textarea", "label": "My urge rating now, and what I chose to do instead of the ritual"}]'::jsonb, array['OCD', 'distress tolerance', 'TIPP']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('ocd-household-load-audit', 'OCD Household Load Audit', 'couples'::resource_kind, 'A worksheet mapping which household tasks have quietly shifted onto the partner without OCD.', 'Use it to renegotiate a fairer division of labor without asking either partner to take over or drop compulsions.', array['Couples']::text[], '30 minutes', 'Family accommodation logs usually track rituals directly; this one tracks the household labor that piles up around them, like grocery shopping handed over because of contamination fears, or nightly door checks the partner starts doing instead. Fill it out together rather than having the partner with OCD complete it alone, since the goal is a negotiated handback, not a confession. Move only one or two tasks at a time and expect the anxious partner''s distress to spike before it settles, which is a sign the audit is working, not a reason to reverse the handback.', '[{"id": "f0", "type": "textarea", "label": "Tasks that have shifted onto my partner because of checking, cleaning, or avoidance on my part"}, {"id": "f1", "type": "textarea", "label": "Tasks my partner has quietly taken over that I want back"}, {"id": "f2", "type": "textarea", "label": "What my partner needs from me before handing a task back"}, {"id": "f3", "type": "textarea", "label": "One task we will move back to me this month, and how"}, {"id": "f4", "type": "textarea", "label": "What my partner will do differently if I ask for reassurance instead of taking the task over"}, {"id": "f5", "type": "textarea", "label": "How we will each know the new split is working"}]'::jsonb, array['OCD', 'couples', 'household tasks']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('shrink-the-ritual-chart', 'Shrink the Ritual Chart', 'kids'::resource_kind, 'A sticker chart that shrinks one compulsion down in small, plotted steps instead of stopping it all at once.', 'Use it to give a child a visible, gradual path off one ritual without asking for a sudden full stop.', array['Children']::text[], 'One to two weeks', 'Build this with the child rather than handing it over finished, since choosing the first step themselves increases follow-through. Pick a ritual that is frequent but not the most distressing one to shrink first, so the early wins are believable. Coach the parent beforehand on responding to the smaller version with the same calm attention as the full ritual, since praising the shrink and getting anxious about the leftover piece undoes the point; the chart should track effort, not a clean finish line, and steps can stay the same size for more than one week if the child needs that.', '[{"id": "f0", "type": "textarea", "label": "The check or ritual we are shrinking (draw or write it)"}, {"id": "f1", "type": "textarea", "label": "How I do it now (how many times, how long)"}, {"id": "f2", "type": "textarea", "label": "Step 1: a slightly smaller version I can try this week"}, {"id": "f3", "type": "textarea", "label": "A sticker or check mark for each day I do the smaller version"}, {"id": "f4", "type": "textarea", "label": "How the worry feeling changed after I tried it"}, {"id": "f5", "type": "textarea", "label": "Step 2: what a smaller version looks like next"}]'::jsonb, array['OCD', 'children', 'exposure']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('interoceptive-exposure-menu', 'Interoceptive Exposure Menu', 'cbt'::resource_kind, 'A menu of body-sensation exercises used to practice interoceptive exposure to panic sensations on purpose.', 'Use it to build a graded list of sensation-inducing exercises so panic sensations lose their alarm value.', array['Adults', 'Teens']::text[], '30 minutes to build, then repeated practice', 'Build the menu from sensations the client actively avoids noticing, not generic exercises, since a straw-breathing drill means nothing if their real trigger is a racing heart after caffeine. Each exercise should be repeated to the point of boredom in a single sitting rather than stopped at the first spike, because it is the repetition inside one practice that teaches the sensation is not dangerous. Rule out any exercise a medical provider has flagged as inappropriate before assigning it as homework.', '[{"id": "f0", "type": "textarea", "label": "The sensation I''m most afraid of feeling (racing heart, dizziness, breathlessness, tight throat)"}, {"id": "f1", "type": "textarea", "label": "Exercise 1 and the sensation it brings on (example: spin in a chair, then dizziness)"}, {"id": "f2", "type": "textarea", "label": "My fear rating for this exercise before I try it (0-10)"}, {"id": "f3", "type": "textarea", "label": "What actually happened when I tried it, and for how long"}, {"id": "f4", "type": "textarea", "label": "My fear rating after several repeats"}, {"id": "f5", "type": "textarea", "label": "The next exercise, chosen because it brings on a sensation I still avoid"}, {"id": "f6", "type": "textarea", "label": "What I''m learning about what these sensations actually mean"}]'::jsonb, array['panic attacks', 'interoceptive exposure', 'sensations']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('panic-choice-point-card', 'Panic Choice Point Card', 'act'::resource_kind, 'An ACT Choice Point diagram applied to the moment right before a panic-driven exit or avoidance move.', 'Use it to make the toward-and-away choice visible in the seconds before a client leaves or cancels out of panic.', array['Adults', 'Teens']::text[], '15 minutes', 'Draw the choice point live in session before sending it home, since clients often cannot name their own away moves until they see one sketched out from a recent panic episode. The card works best kept somewhere they will see it right before entering a feared situation, not filed away with other worksheets. Expect the first few uses to end in the away move anyway; the goal at first is just noticing the choice point exists, not winning it every time.', '[{"id": "f0", "type": "textarea", "label": "The situation where panic tends to show up"}, {"id": "f1", "type": "textarea", "label": "What panic is telling me to do (leave, cancel, avoid)"}, {"id": "f2", "type": "textarea", "label": "What that away move costs me, over time"}, {"id": "f3", "type": "textarea", "label": "What I actually care about being able to do here"}, {"id": "f4", "type": "textarea", "label": "A toward move I could make instead, even a small one"}, {"id": "f5", "type": "textarea", "label": "What I''ll say to myself right at the choice point"}]'::jsonb, array['panic attacks', 'choice point', 'values']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('rebuilding-shared-outings-plan', 'Rebuilding Shared Outings Plan', 'couples'::resource_kind, 'A plan for a couple to gradually reclaim outings and activities scaled back because of panic.', 'Use it to rebuild a shared life around panic without either partner having to force a full return at once.', array['Couples']::text[], 'Ongoing, reviewed every few weeks', 'Couples often narrow their shared life gradually enough that neither partner notices how much has been dropped until this list is in front of them. The partner without panic usually wants to help by taking over logistics or staying unusually close, and this plan asks them to trade that role for something more useful: encouraging the smaller version and resisting the urge to rescue if things get uncomfortable. Choose activities either partner misses, not just the ones that look most impressive to fix first.', '[{"id": "f0", "type": "textarea", "label": "Activities we used to do together that we''ve cut back or stopped"}, {"id": "f1", "type": "textarea", "label": "What I''m afraid will happen if we try one again"}, {"id": "f2", "type": "textarea", "label": "What my partner has been doing to help me avoid it (driving a certain way, staying close by, checking in constantly)"}, {"id": "f3", "type": "textarea", "label": "One activity we''ll try again this month, in a smaller version"}, {"id": "f4", "type": "textarea", "label": "What my partner will do instead of the usual safety habit"}, {"id": "f5", "type": "textarea", "label": "How we''ll each know the smaller version counts as a win"}]'::jsonb, array['panic attacks', 'couples', 'avoidance']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('big-wave-body-map', 'Big Wave Body Map', 'kids'::resource_kind, 'A body outline a child colors to mark where panic sensations show up, paired with a calm-down step list.', 'Use it to help a child name and locate sudden scary body feelings and pick calming steps in advance.', array['Children']::text[], '20 minutes', 'Some children experience panic without any language for it beyond ''I feel sick'' or ''something bad is happening,'' and mapping the sensations onto a body outline gives them words before asking them to use a coping skill. Do the coloring together in session first so the clinician can hear the child''s own descriptions rather than supplying words for them. Coach the parent to use the same body-part language at home in the moment, asking whether this is a tummy wave or a heart wave, rather than asking the child to explain from scratch every time.', '[{"id": "f0", "type": "textarea", "label": "Color the spots on my body where the big wave shows up (heart, tummy, throat, hands)"}, {"id": "f1", "type": "textarea", "label": "What each spot feels like (pounding, tight, shaky, hot)"}, {"id": "f2", "type": "textarea", "label": "What my body thinks is happening"}, {"id": "f3", "type": "textarea", "label": "What is really happening (my body''s alarm going off, not real danger)"}, {"id": "f4", "type": "textarea", "label": "My first calm-down step"}, {"id": "f5", "type": "textarea", "label": "Who I can go to when the big wave hits"}]'::jsonb, array['panic attacks', 'children', 'body awareness']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('panic-sensation-match', 'Panic Sensation Match', 'game'::resource_kind, 'A matching game pairing panic sensations with what is actually happening in the body, played in a group.', 'Use it to replace catastrophic misreadings of body sensations with realistic ones through repeated matching.', array['Adults', 'Teens', 'Groups']::text[], '20 minutes', 'Deal sensation cards, such as racing heart or tight chest, and explanation cards, such as adrenaline releasing or blood moving to the muscles, face down in two piles; players take turns flipping one of each and deciding whether they match, with the group correcting mismatches together. Keep one deliberately wrong explanation card in the deck to spark debate, since arguing over a bad match does more for belief change than a clean correct answer. Close with the debrief questions rather than moving straight on, since that''s where sensations connect back to each player''s own panic pattern.', '[{"id": "f0", "type": "textarea", "label": "Sensation cards we used"}, {"id": "f1", "type": "textarea", "label": "Explanation cards we used"}, {"id": "f2", "type": "textarea", "label": "A match that surprised someone"}, {"id": "f3", "type": "textarea", "label": "A sensation someone still finds hard to believe is harmless"}, {"id": "f4", "type": "textarea", "label": "What we''ll each do next time that sensation shows up"}]'::jsonb, array['panic attacks', 'group', 'play']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('behavior-priority-sort', 'Behavior Priority Sort', 'worksheet'::resource_kind, 'A worksheet sorting a child''s behaviors into address now, watch, and let go, so a parent isn''t fighting every battle.', 'Use it to help a parent choose one or two target behaviors instead of reacting to everything at once.', array['Adults']::text[], '20 minutes', 'Parents usually arrive with a much longer list than two behaviors, and this worksheet is where that list gets narrowed down rather than acted on directly. The let-go column tends to be the hardest to fill in and the most useful, since spreading attention across ten behaviors usually means none of them actually change. Revisit the sort every few weeks rather than adding new behaviors to an already full address-now column.', '[{"id": "f0", "type": "textarea", "label": "Every behavior currently frustrating me, listed without editing"}, {"id": "f1", "type": "textarea", "label": "Which ones feel most urgent, and why"}, {"id": "f2", "type": "textarea", "label": "Behaviors I''ll address now (no more than two)"}, {"id": "f3", "type": "textarea", "label": "Behaviors I''ll watch but not react to yet"}, {"id": "f4", "type": "textarea", "label": "Behaviors I''m choosing to let go of for now, and what I''ll say to myself when I want to react anyway"}, {"id": "f5", "type": "textarea", "label": "What consistent response I''ll use for each address-now behavior"}]'::jsonb, array['parenting', 'behavioral', 'consistency']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('willingness-to-hold-the-limit-practice', 'Willingness to Hold the Limit Practice', 'act'::resource_kind, 'An ACT willingness practice for staying present through a child''s protest instead of giving in to end the discomfort.', 'Use it to help a parent hold a boundary by making room for guilt and distress rather than avoiding them.', array['Adults']::text[], '15 minutes', 'Most caving happens because a parent is trying to make their own discomfort go away, not because the limit was wrong, and this practice separates those two things. Have the client rehearse the willingness language out loud before the next likely protest, since it needs to be available in the moment, not just written down. This pairs well with a values conversation about the kind of parent they want to be, since willingness without a clear reason to hold the line rarely survives a real protest.', '[{"id": "f0", "type": "textarea", "label": "The limit I keep caving on"}, {"id": "f1", "type": "textarea", "label": "What shows up in me right before I give in (guilt, their crying, my own anxiety)"}, {"id": "f2", "type": "textarea", "label": "What giving in actually costs, over time, for both of us"}, {"id": "f3", "type": "textarea", "label": "The kind of parent I want to be in this moment, even if it''s uncomfortable"}, {"id": "f4", "type": "textarea", "label": "What I can say to myself while I make room for the discomfort and hold the limit anyway"}, {"id": "f5", "type": "textarea", "label": "What I noticed the last time I held it despite the urge to give in"}]'::jsonb, array['parenting', 'willingness', 'boundaries']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-parent-guilt-card', 'Opposite Action for Parent Guilt Card', 'dbt'::resource_kind, 'A DBT opposite action card for when parent guilt urges giving in, apologizing excessively, or over-explaining a limit.', 'Use it to help a parent check whether guilt fits the facts and act opposite to it when it doesn''t.', array['Adults']::text[], '10 minutes', 'Parent guilt is one of the more common places opposite action gets skipped in favor of just talking the guilt through, but the DBT move here is behavioral: check whether the guilt fits the facts, and if it doesn''t, act the opposite of what it''s pushing for instead of processing it further. Watch for the over-explaining pattern in particular, since a parent who re-justifies a fair limit to their child is usually acting on the guilt rather than the facts. This pairs well with a parent who has already tried thought-based guilt work and keeps caving anyway.', '[{"id": "f0", "type": "textarea", "label": "The limit I set that triggered guilt"}, {"id": "f1", "type": "textarea", "label": "What the guilt is telling me to do (undo it, over-explain, apologize repeatedly)"}, {"id": "f2", "type": "textarea", "label": "Does the guilt fit the facts? Was the limit fair, safe, and reasonable for their age?"}, {"id": "f3", "type": "textarea", "label": "If the guilt doesn''t fit, the opposite action I''ll take instead"}, {"id": "f4", "type": "textarea", "label": "How I''ll say the limit differently next time, without over-explaining"}, {"id": "f5", "type": "textarea", "label": "What happened when I acted opposite to the guilt"}]'::jsonb, array['parenting', 'opposite action', 'guilt']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('teamwork-badge-craft', 'Teamwork Badge Craft', 'kids'::resource_kind, 'A badge children design and earn for cooperating with a sibling, spotted and named by a coached parent.', 'Use it to build sibling cooperation through immediate, specific parent praise rather than after-the-fact rewards.', array['Children']::text[], '20 minutes to make, then ongoing', 'Make the badge with the children rather than printing one, since a badge they designed themselves gets more mileage than a generic sticker chart. Coach the parent beforehand to name the specific cooperative behavior out loud the moment they see it, rather than waiting until the end of the day, since the timing does more work than the badge itself. Let children award a badge to a sibling occasionally too; that peer-to-peer praise often lands harder than anything from a parent.', '[{"id": "f0", "type": "textarea", "label": "Design my teamwork badge (draw and color it)"}, {"id": "f1", "type": "textarea", "label": "What teamwork looks like that earns the badge (sharing, taking turns, helping)"}, {"id": "f2", "type": "textarea", "label": "A time this week I earned it"}, {"id": "f3", "type": "textarea", "label": "What my grown-up said when they noticed"}, {"id": "f4", "type": "textarea", "label": "Who I want to give a badge to next"}]'::jsonb, array['parenting', 'children', 'cooperation']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('rules-and-rewards-sorting-game', 'Rules and Rewards Sorting Game', 'game'::resource_kind, 'A family card-sorting game matching behaviors to earned privileges or consequences to build one shared rule set.', 'Use it to get everyone in the family sorting behaviors the same way before a real consequence is ever on the line.', array['Children', 'Adults', 'Groups']::text[], '25 minutes', 'Write behavior cards from real recent conflicts rather than generic examples, and shuffle in a couple of trick cards, like a chore done badly on purpose, to spark real disagreement. Each player takes a turn drawing a card and proposing where it goes, whether it earns a privilege, gets a consequence, or is a warning first, and the family has to reach agreement before it''s placed. Run the debrief with the rule that whatever gets agreed on today gets used consistently this week, since the game only helps if it produces a rule that actually gets enforced afterward.', '[{"id": "f0", "type": "textarea", "label": "Behavior cards we sorted"}, {"id": "f1", "type": "textarea", "label": "Where we disagreed on a card, and how we settled it"}, {"id": "f2", "type": "textarea", "label": "The final house rule for that behavior"}, {"id": "f3", "type": "textarea", "label": "A card that surprised someone once it was discussed"}, {"id": "f4", "type": "textarea", "label": "What we''ll do differently now that we''ve agreed"}]'::jsonb, array['parenting', 'family', 'game night']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('infant-feeding-stress-support-plan', 'Infant Feeding Stress and Support Plan', 'worksheet'::resource_kind, 'A worksheet for naming feeding worries and lining up support before the next hard feed.', 'Use it to turn free-floating stress about feeding choices into a concrete support plan.', array['Adults']::text[], '20 minutes', 'Feeding decisions in the early weeks, whether breast, bottle, pumping, or some mix, tend to carry an outsized amount of judgment from strangers, family, and social media. Use this after a rough feed or a comment that stuck, not as a lactation consult substitute; route feeding logistics themselves to a lactation consultant or pediatrician and use this sheet for the emotional side. Watch for comparison to other parents doing it differently.', '[{"id": "f0", "type": "textarea", "label": "What the feeding plan looked like before birth, and how it has actually gone"}, {"id": "f1", "type": "textarea", "label": "Comments or comparisons that have stuck with me"}, {"id": "f2", "type": "textarea", "label": "What I actually need right now around feeding"}, {"id": "f3", "type": "textarea", "label": "Who could help with this: partner, family, lactation support, pediatrician"}, {"id": "f4", "type": "textarea", "label": "One way I can ask for that help this week"}, {"id": "f5", "type": "textarea", "label": "A reminder to myself for the next hard feed"}]'::jsonb, array['perinatal and postpartum', 'feeding', 'support']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('sleep-deprived-thinking-check', 'Sleep-Deprived Thinking Check', 'cbt'::resource_kind, 'A short thought record for catching catastrophic thinking that spikes with newborn sleep loss.', 'Use it to slow down conclusions drawn in the middle of the night until rest returns.', array['Adults']::text[], 'Ten minutes', 'Sleep deprivation reliably intensifies catastrophizing, mind reading, and black-and-white thinking in new parents, and thoughts that feel like facts at 3 a.m. often look different by mid-morning. Use this in the moment after a distressing thought rather than as a nightly homework habit, and keep it brief since attention and patience are both in short supply. Track hours of sleep alongside belief ratings so the pattern becomes visible over a few uses.', '[{"id": "f0", "type": "textarea", "label": "The thought that showed up"}, {"id": "f1", "type": "textarea", "label": "How many hours of sleep I have had in the last 24"}, {"id": "f2", "type": "textarea", "label": "How much I believed the thought in the moment, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "What a rested version of me might say back"}, {"id": "f4", "type": "textarea", "label": "One thing that would actually help right now"}, {"id": "f5", "type": "textarea", "label": "How much I believe the thought now"}]'::jsonb, array['perinatal and postpartum', 'sleep', 'thinking traps']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('new-parent-help-asking-dear-man', 'New Parent Help-Asking DEAR MAN', 'dbt'::resource_kind, 'A DEAR MAN script for asking a partner or relative for one concrete piece of baby help.', 'Use it to turn a vague wish for help into a single, specific, askable request.', array['Adults']::text[], '20 minutes', 'New parents often carry a wish for help that never gets voiced as an actual ask, partly from guilt and partly from not knowing what to request. Apply the standard DEAR MAN structure to one narrow, concrete ask, such as a single night feed or an hour of coverage, rather than a general plea for more support. Coach the client to pick the smallest workable request first so the skill has a good chance of landing, then build from there.', '[{"id": "f0", "type": "textarea", "label": "Describe: what is actually happening right now, just the facts"}, {"id": "f1", "type": "textarea", "label": "Express: how this is affecting me"}, {"id": "f2", "type": "textarea", "label": "Assert: the one specific thing I am asking for"}, {"id": "f3", "type": "textarea", "label": "Reinforce: how it will help both of us if they say yes"}, {"id": "f4", "type": "textarea", "label": "Staying mindful: what I will do if they change the subject or say no at first"}, {"id": "f5", "type": "textarea", "label": "Appearing confident: how I want to sound saying this"}, {"id": "f6", "type": "textarea", "label": "Negotiate: something I could offer or adjust"}]'::jsonb, array['perinatal and postpartum', 'DEAR MAN', 'interpersonal effectiveness']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('new-parent-visitor-boundaries-agreement', 'New Parent Visitor Boundaries Agreement', 'couples'::resource_kind, 'A joint planning sheet for agreeing on visitor limits before a newborn''s first houseguests arrive.', 'Use it to help both partners settle visitor rules before conflict erupts in the moment.', array['Couples']::text[], '25 minutes', 'Partners often carry different family expectations about visiting a newborn, and exhaustion turns small disagreements about houseguests into flashpoints fast. Best used before the baby arrives or as early as possible after, this sheet has each partner name their own hopes and worries before negotiating shared rules, so neither person is blindsided later. Push for specifics on notice, length of visit, and what visitors can help with rather than vague good intentions.', '[{"id": "f0", "type": "textarea", "label": "Partner A''s honest hopes and worries about visitors"}, {"id": "f1", "type": "textarea", "label": "Partner B''s honest hopes and worries about visitors"}, {"id": "f2", "type": "textarea", "label": "What we agree we both need in the first few weeks"}, {"id": "f3", "type": "textarea", "label": "Our shared rules: notice, length of visit, what visitors can help with"}, {"id": "f4", "type": "textarea", "label": "The one relative or situation we expect to be hardest"}, {"id": "f5", "type": "textarea", "label": "What Partner A will say if that boundary gets pushed"}, {"id": "f6", "type": "textarea", "label": "What Partner B will say if that boundary gets pushed"}, {"id": "f7", "type": "textarea", "label": "How we will check in with each other afterward"}]'::jsonb, array['perinatal and postpartum', 'boundaries', 'family']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('fourth-trimester-trivia-challenge', 'Fourth Trimester Trivia Challenge', 'game'::resource_kind, 'A trivia game where new parents guess what actually counts as normal after birth.', 'Use it to normalize common fourth-trimester experiences and ease isolating comparison.', array['Adults', 'Groups']::text[], '25 minutes', 'Read out a mix of statements about postpartum bodies, moods, sleep, and baby behavior, and have players vote true or false before you reveal the answer and award a point for each correct guess. This works especially well in new-parent groups, where hearing that a strange or hard experience is widely shared does more to ease isolation than reassurance alone. Keep statements general rather than citing specific numbers, and leave time to debrief on what felt most reassuring.', '[{"id": "f0", "type": "textarea", "label": "Statements our group guessed correctly"}, {"id": "f1", "type": "textarea", "label": "Statements our group got wrong"}, {"id": "f2", "type": "textarea", "label": "The one ''normal'' fact that surprised me most"}, {"id": "f3", "type": "textarea", "label": "Something happening for me that I now feel less alone in"}, {"id": "f4", "type": "textarea", "label": "A myth about new parenthood I want to let go of"}]'::jsonb, array['perinatal and postpartum', 'group', 'play']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('self-worth-timeline-review', 'Self-Worth Timeline Review', 'worksheet'::resource_kind, 'A timeline mapping how a client''s sense of self-worth has shifted across major life periods.', 'Use it to locate when self-worth took a hit and what has protected it since.', array['Adults']::text[], 'Full session', 'Segment the client''s life into rough chunks such as childhood, school years, early adulthood, and now, then rate self-worth in each period before looking for the events or relationships that shaped the drops and rises. This works well early in self-esteem-focused work to build a shared formulation, giving both of you a map rather than a single flat story. Watch for one especially hard stretch coming to define the whole line, and ask what was still true about the client even then.', '[{"id": "f0", "type": "textarea", "label": "Life periods I will map, for example childhood, school years, early adulthood, now"}, {"id": "f1", "type": "textarea", "label": "My self-worth rating in each period, low to high"}, {"id": "f2", "type": "textarea", "label": "What was happening in the periods where it dropped"}, {"id": "f3", "type": "textarea", "label": "What was happening in the periods where it rose"}, {"id": "f4", "type": "textarea", "label": "A pattern I notice looking at the whole line"}, {"id": "f5", "type": "textarea", "label": "What I want the next stretch of the line to look like"}]'::jsonb, array['self-esteem', 'life review', 'formulation']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('self-worth-behavioral-experiment', 'Self-Worth Behavioral Experiment', 'cbt'::resource_kind, 'A behavioral experiment testing self-worth predictions against what actually happens.', 'Use it to test beliefs like ''no one wants my opinion'' against real evidence, not just a feeling.', array['Adults']::text[], 'One week', 'Unlike a general behavioral experiment, this one is anchored specifically to a self-worth belief such as ''if I speak up I''ll be seen as less than'' or ''if I say no, I''ll lose the relationship.'' Have the client pick a small, low-stakes action that would test the belief, predict the outcome and rate their belief before acting, then record what actually happened afterward. Running several small experiments across different situations builds an evidence base that outweighs any single bad memory.', '[{"id": "f0", "type": "textarea", "label": "The self-worth belief I am testing"}, {"id": "f1", "type": "textarea", "label": "How much I believe it right now, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "The small action I will take to test it"}, {"id": "f3", "type": "textarea", "label": "What I predict will happen"}, {"id": "f4", "type": "textarea", "label": "What actually happened"}, {"id": "f5", "type": "textarea", "label": "How much I believe the original belief now"}, {"id": "f6", "type": "textarea", "label": "What this experiment adds to my evidence"}]'::jsonb, array['self-esteem', 'behavioral experiment', 'belief change']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('scorecard-mind-defusion', 'Scorecard Mind Defusion', 'act'::resource_kind, 'A defusion exercise for the part of the mind that constantly scores and ranks self-worth.', 'Use it to notice the scorekeeping voice without automatically treating its verdicts as fact.', array['Adults']::text[], '20 minutes', 'Introduce the metaphor of a ''scorecard mind'' that keeps a running tally, adding and subtracting points for looks, achievement, or mistakes, and comparing the total to everyone else''s. Have the client describe how their own scorecard talks, notice where it shows up in the body, and practice a short defusion phrase such as ''there''s the scorecard again'' to create some distance from it. The aim is not to silence the voice or win an argument with it, but to keep acting on values even while it is running.', '[{"id": "f0", "type": "textarea", "label": "What my scorecard mind tends to keep tabs on"}, {"id": "f1", "type": "textarea", "label": "A recent score it handed me, and what triggered it"}, {"id": "f2", "type": "textarea", "label": "What I notice in my body when it is adding up points"}, {"id": "f3", "type": "textarea", "label": "A phrase I can use to notice it out loud"}, {"id": "f4", "type": "textarea", "label": "Something I would do today if the score did not get a vote"}]'::jsonb, array['self-esteem', 'defusion', 'acceptance']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('partner-evidence-exchange-self-worth', 'Partner Evidence Exchange for Self-Worth', 'couples'::resource_kind, 'A structured exchange where each partner offers specific evidence for the other''s worth.', 'Use it to build an external evidence bank a partner with low self-worth can draw on later.', array['Couples']::text[], '25 minutes', 'Have each partner separately write several specific, concrete examples of times the other showed competence, kindness, or worth, rather than general compliments, then take turns reading them aloud. The listening partner records which examples land hardest and keeps a couple to reread later. This supplements rather than replaces the client''s own internal evidence-building work, so watch for a partner who slides into blanket reassurance instead of naming specifics.', '[{"id": "f0", "type": "textarea", "label": "Partner A''s specific examples of Partner B''s worth, not general compliments"}, {"id": "f1", "type": "textarea", "label": "Partner B''s specific examples of Partner A''s worth, not general compliments"}, {"id": "f2", "type": "textarea", "label": "Which example landed hardest for Partner A, and why"}, {"id": "f3", "type": "textarea", "label": "Which example landed hardest for Partner B, and why"}, {"id": "f4", "type": "textarea", "label": "One example each of us will keep and reread this week"}]'::jsonb, array['self-esteem', 'relationship issues', 'evidence log']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('i-am-statements-mirror-frame', 'I Am Statements Mirror Frame', 'kids'::resource_kind, 'A decorated mirror frame craft that displays a child''s own positive ''I am'' statements.', 'Use it to give a child daily visual reminders of strengths they picked for themselves.', array['Children']::text[], '30 minutes', 'The child decorates a cardboard frame, or borders a real mirror with removable stickers, then writes or dictates several ''I am'' statements such as brave, kind, or a good helper around the edge. A parent or caregiver mounts it by the child''s mirror at home and is asked to read it aloud together at a set moment, like before school. Watch for children reaching for statements that please the adults in the room, and gently redirect toward specific things the child has actually done.', '[{"id": "f0", "type": "textarea", "label": "Words or pictures I want on my frame"}, {"id": "f1", "type": "textarea", "label": "My ''I am'' statements"}, {"id": "f2", "type": "textarea", "label": "Where at home this will go"}, {"id": "f3", "type": "textarea", "label": "Who will read it with me, and when"}]'::jsonb, array['self-esteem', 'children', 'art']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('visible-anxiety-symptom-belief-test', 'Visible Anxiety Symptom Belief Test', 'cbt'::resource_kind, 'A behavioral experiment testing beliefs about how visible anxiety symptoms are to others.', 'Use it to compare predicted visibility of blushing or shaking with what others actually notice.', array['Adults', 'Teens']::text[], 'One week', 'Many clients with social anxiety believe blushing, shaking, or sweating are far more obvious than they really are. Before a feared situation, have the client rate how visible they predict a symptom will be, then afterward compare that with actual evidence, whether from a trusted person''s honest report or their own observation of others'' reactions. Safety behaviors such as covering the face or avoiding eye contact will contaminate the result, so agree in advance to drop them for this test.', '[{"id": "f0", "type": "textarea", "label": "The situation and the physical symptom I am worried will show"}, {"id": "f1", "type": "textarea", "label": "How visible I predict it will be to others, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "How anxious that prediction makes me, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "What actually happened, and any evidence I gathered"}, {"id": "f4", "type": "textarea", "label": "How visible it actually seemed to others, 0 to 100"}, {"id": "f5", "type": "textarea", "label": "What I am taking from the gap between prediction and reality"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'belief change']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('critic-in-the-crowd-defusion', 'Critic in the Crowd Defusion', 'act'::resource_kind, 'A defusion practice for the felt sense that everyone in a room is silently judging.', 'Use it to create distance from the ''critic in the crowd'' story without arguing it away.', array['Adults', 'Teens']::text[], '20 minutes', 'In social situations the mind often narrates a ''critic in the crowd'' who is watching and judging every move, even when no one nearby is paying that much attention. Ask the client to describe this critic''s voice and favorite lines, notice where it shows up in the body, and rehearse a short defusion phrase such as ''there''s the critic again'' to use before and during a mildly feared social moment. This pairs well with exposure work and a values-based reason for showing up anyway, rather than replacing either.', '[{"id": "f0", "type": "textarea", "label": "What the critic in the crowd usually says"}, {"id": "f1", "type": "textarea", "label": "Where I feel it show up in my body"}, {"id": "f2", "type": "textarea", "label": "A situation where the critic gets loudest"}, {"id": "f3", "type": "textarea", "label": "My defusion phrase for noticing it"}, {"id": "f4", "type": "textarea", "label": "What I would do in that situation if the critic did not get a vote"}]'::jsonb, array['social anxiety', 'defusion', 'acceptance']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('pre-event-tipp-reset', 'Pre-Event TIPP Reset', 'dbt'::resource_kind, 'A TIPP-based routine for calming physical arousal in the minutes before a feared social event.', 'Use it to bring arousal down before overwhelm can shape a decision to avoid.', array['Adults', 'Teens']::text[], 'Ten minutes', 'Adapt the DBT TIPP skill, temperature, intense exercise, paced breathing, and paired muscle relaxation, to the narrow window right before something like a party, meeting, or date. Help the client pick which pieces are realistic to do in a car, a bathroom, or a hallway on the way in, since not every option fits every setting. Check temperature options such as cold water on the face against any relevant medical conditions, and keep intense exercise brief and appropriate to the client''s fitness.', '[{"id": "f0", "type": "textarea", "label": "The event I am using this before"}, {"id": "f1", "type": "textarea", "label": "My arousal level right before starting, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "Which TIPP option I will use here"}, {"id": "f3", "type": "textarea", "label": "Where and how I will actually do it"}, {"id": "f4", "type": "textarea", "label": "My arousal level right after"}, {"id": "f5", "type": "textarea", "label": "What I will do next, however I am feeling"}]'::jsonb, array['social anxiety', 'TIPP', 'distress tolerance']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('meeting-someone-new-puppet-script', 'Meeting Someone New Puppet Script', 'kids'::resource_kind, 'A puppet-and-script craft where a child builds and rehearses lines for meeting a new peer.', 'Use it to rehearse a simple greeting script until it feels less unfamiliar out loud.', array['Children']::text[], '30 minutes', 'Have the child make a simple puppet from a paper bag, sock, or cutout, then write a short script together for meeting someone new: a name, one question, and one line for if the other kid says something unexpected. Practice with the puppet doing the talking first, then have the child speak the same lines as themselves. Ask the caregiver to run through the script once at home before the next real chance to use it, keeping the tone playful rather than like a test to pass.', '[{"id": "f0", "type": "textarea", "label": "My puppet''s name"}, {"id": "f1", "type": "textarea", "label": "What I will say first when I meet someone new"}, {"id": "f2", "type": "textarea", "label": "One question I can ask them"}, {"id": "f3", "type": "textarea", "label": "What I will say if they say something I do not expect"}, {"id": "f4", "type": "textarea", "label": "Who I practiced this with at home"}]'::jsonb, array['social anxiety', 'children', 'role play']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('eye-contact-challenge-game', 'Eye Contact Challenge Game', 'game'::resource_kind, 'A paired game that builds tolerance for eye contact through short, escalating rounds.', 'Use it to make eye contact feel like a game with rules, not a test to fail.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Pair players up and hold eye contact for a set number of seconds each round, starting around three and building up, then break and rate discomfort before rotating partners in a group setting. Add a silly variant where the first person to laugh restarts the round, which keeps the exercise light rather than tense. Debrief afterward on how discomfort shifted from the first round to the last, and where else eye contact tends to get avoided day to day. Let anyone skip a round without needing to explain why.', '[{"id": "f0", "type": "textarea", "label": "Starting discomfort rating before round one, 0 to 100"}, {"id": "f1", "type": "textarea", "label": "How long we held eye contact each round"}, {"id": "f2", "type": "textarea", "label": "Discomfort rating after the last round"}, {"id": "f3", "type": "textarea", "label": "What changed between round one and the last round"}, {"id": "f4", "type": "textarea", "label": "One place outside this room where I avoid eye contact"}]'::jsonb, array['social anxiety', 'exposure', 'play']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('ambiguous-loss-inventory', 'Ambiguous Loss Inventory', 'worksheet'::resource_kind, 'Helps a client name and validate a loss that others may not recognize as grief-worthy.', 'Use it to validate grief that friends and family have dismissed or overlooked.', array['Adults']::text[], '30 minutes', 'Ambiguous loss covers grief that lacks a funeral or a clear ending — a friendship that faded, an estrangement, a miscarriage, a health condition that changed who someone was while they were still alive. Clients often arrive apologizing for grieving "something that doesn''t count." Normalize the loss before moving through the prompts, and expect some clients to surface more sadness or anger than they anticipated once it is named directly.', '[{"id": "f0", "type": "textarea", "label": "What did I lose, even though no one else may call it a loss?"}, {"id": "f1", "type": "textarea", "label": "What has made it hard for others to recognize this loss?"}, {"id": "f2", "type": "textarea", "label": "What have I told myself I''m not allowed to feel about it?"}, {"id": "f3", "type": "textarea", "label": "Who, if anyone, has acknowledged this loss with me?"}, {"id": "f4", "type": "textarea", "label": "What would I want someone to say to me about it?"}, {"id": "f5", "type": "textarea", "label": "One way I can honor this loss on my own terms"}]'::jsonb, array['grief and loss', 'disenfranchised grief', 'validation']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('grief-coping-workability-sort', 'Grief Coping Workability Sort', 'act'::resource_kind, 'A card sort that checks whether a grief coping habit moves a client toward or away from their values.', 'Use it to replace judgment about coping choices with a workability lens.', array['Adults']::text[], '20 minutes', 'Write a list of grief-related coping behaviors — avoiding photos, staying busy, drinking more, isolating, visiting the grave weekly, talking about the person often — on cards ahead of time, or build the list with the client first. Sort each into workable or costly, then discuss the ones that land in both piles, since most do. The goal isn''t to eliminate coping behaviors but to notice which ones the client wants to keep on purpose versus which ones have quietly taken over.', '[{"id": "f0", "type": "textarea", "label": "A coping behavior I sorted into ''moves me toward my values''"}, {"id": "f1", "type": "textarea", "label": "A coping behavior I sorted into ''moves me away from my values''"}, {"id": "f2", "type": "textarea", "label": "A behavior that landed in both piles, and why"}, {"id": "f3", "type": "textarea", "label": "One coping behavior I want to keep on purpose"}, {"id": "f4", "type": "textarea", "label": "One coping behavior I want to loosen my grip on"}]'::jsonb, array['grief and loss', 'values', 'workability']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('grief-burst-distress-skills-card', 'Grief Burst Distress Skills Card', 'dbt'::resource_kind, 'A pocket card matching sudden waves of grief to a quick distress tolerance skill.', 'Use it to give clients a fast, rehearsed response when a grief burst hits without warning.', array['Adults', 'Teens']::text[], '15 minutes', 'Grief bursts arrive without much warning — a song, a smell, an empty chair at dinner — and clients often feel ambushed by their own reaction in public or at work. Build the card together in session by matching a few known triggers to a specific, already-rehearsed skill such as paced breathing, a cold-water reset, stepping outside, or texting a support person, rather than leaving the response to be improvised in the moment. Revisit and edit the card as new triggers show up.', '[{"id": "f0", "type": "textarea", "label": "A trigger that tends to set off a grief burst for me"}, {"id": "f1", "type": "textarea", "label": "The first thing I will do in the first 60 seconds"}, {"id": "f2", "type": "textarea", "label": "A skill I can use if I''m in public and can''t step away"}, {"id": "f3", "type": "textarea", "label": "Who I can text or call afterward"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself while the wave passes"}]'::jsonb, array['grief and loss', 'distress tolerance', 'coping skills']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('reconnecting-after-loss-conversation', 'Reconnecting After Loss Conversation', 'couples'::resource_kind, 'A guided conversation for partners to check in on the closeness a shared loss has disrupted.', 'Use it to help a grieving couple rebuild connection without pressuring either partner''s pace.', array['Couples']::text[], '30 minutes', 'Grief can pull partners apart even when the loss is shared — one partner may want closeness while the other withdraws, or both quietly stop reaching for each other. Run this in session first so each partner can hear the other''s answers without feeling ambushed at home, and watch for one partner using the loss as a reason to avoid an older disconnect that predates it. This is about noticing distance and naming small steps back, not about resolving the grief itself.', '[{"id": "f0", "type": "textarea", "label": "Since the loss, what I miss most about how we used to connect"}, {"id": "f1", "type": "textarea", "label": "A moment recently when I felt closer to my partner"}, {"id": "f2", "type": "textarea", "label": "A moment recently when I felt more distant"}, {"id": "f3", "type": "textarea", "label": "One small thing my partner could do that would help me feel less alone"}, {"id": "f4", "type": "textarea", "label": "One small thing I am willing to try this week"}]'::jsonb, array['grief and loss', 'intimacy', 'communication']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('grief-myths-and-facts-showdown', 'Grief Myths and Facts Showdown', 'game'::resource_kind, 'A card game where players guess whether a statement about grief is a myth or a fact.', 'Use it to correct unhelpful beliefs about grief timelines, stages, and moving on.', array['Adults', 'Teens', 'Groups']::text[], '25 minutes', 'Prepare a deck of statements such as "grief moves through five stages in order" or "you should be over it after a year" mixed with accurate statements, then have players guess myth or fact before you reveal the answer and discuss. The debrief matters more than the score — pause on any myth a player believed personally, since these are often the exact beliefs driving guilt about grieving "wrong" or too long.', '[{"id": "f0", "type": "textarea", "label": "A myth I used to believe about grief"}, {"id": "f1", "type": "textarea", "label": "A fact that surprised me"}, {"id": "f2", "type": "textarea", "label": "A belief about grief I inherited from my family"}, {"id": "f3", "type": "textarea", "label": "What I would tell someone else about how grief actually works"}]'::jsonb, array['grief and loss', 'psychoeducation', 'group']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('relationship-pattern-timeline', 'Relationship Pattern Timeline', 'worksheet'::resource_kind, 'A worksheet mapping the relationship dynamic a client keeps repeating across different partners.', 'Use it to help a client see a pattern clearly before deciding whether to repeat or change it.', array['Adults']::text[], '30 minutes', 'This is individual work, done without a partner in the room, looking across two or three past or present relationships for a repeating role, dynamic, or turning point. Clients sometimes resist at first, worried this will turn into blaming themselves for everything that went wrong; frame it as pattern-spotting rather than fault-finding. The most useful moment is usually the last prompt, where the client names what they''d want to do differently now that the pattern is visible.', '[{"id": "f0", "type": "textarea", "label": "Relationship one: what role did I tend to play?"}, {"id": "f1", "type": "textarea", "label": "Relationship two: what role did I tend to play?"}, {"id": "f2", "type": "textarea", "label": "What tends to happen around the point things start to break down?"}, {"id": "f3", "type": "textarea", "label": "What do these relationships have in common?"}, {"id": "f4", "type": "textarea", "label": "What part of the pattern is mine to change?"}, {"id": "f5", "type": "textarea", "label": "What do I want to do differently going forward?"}]'::jsonb, array['relationship issues', 'pattern', 'life review']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('relationship-catastrophizing-thought-record', 'Relationship Catastrophizing Thought Record', 'cbt'::resource_kind, 'A thought record for catching all-or-nothing predictions about a relationship''s future during conflict.', 'Use it to slow down thoughts like this always happens before they drive a bigger reaction.', array['Adults', 'Couples']::text[], '20 minutes', 'Best used shortly after a disagreement, while the memory is fresh but the client is no longer flooded. Watch for the classic relationship catastrophizing moves — "we always fight about this," "this proves we''re incompatible," "it''s never going to change" — and help the client separate the specific incident from the sweeping verdict attached to it. This works well paired with a calmer follow-up conversation once the thought has been challenged rather than acted on.', '[{"id": "f0", "type": "textarea", "label": "What happened, in a few neutral sentences"}, {"id": "f1", "type": "textarea", "label": "The catastrophic thought that showed up"}, {"id": "f2", "type": "textarea", "label": "How much I believed it in the moment, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "Evidence that doesn''t fit this thought"}, {"id": "f4", "type": "textarea", "label": "A more balanced way to think about this one incident"}, {"id": "f5", "type": "textarea", "label": "How much I believe the catastrophic thought now, 0 to 100"}]'::jsonb, array['relationship issues', 'thought record', 'thinking traps']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('wise-mind-pause-before-the-hard-talk', 'Wise Mind Pause Before the Hard Talk', 'dbt'::resource_kind, 'A short check-in that helps a client find wise mind before raising a sensitive relationship topic.', 'Use it to replace impulsive blow-ups or silent avoidance with a chosen, wise-mind approach.', array['Adults', 'Couples']::text[], '10 minutes', 'This is meant to be used in the five minutes before a client raises something difficult with a partner, not analyzed after the fact. Have them rate whether they''re closer to emotion mind or reasonable mind, name the urge each is pulling toward such as attacking or saying nothing at all, and choose one wise-mind opening line before they start the conversation. Clients who tend to avoid entirely and clients who tend to escalate get different value from this, so tailor the debrief to which pattern shows up.', '[{"id": "f0", "type": "textarea", "label": "What I want to raise with my partner"}, {"id": "f1", "type": "textarea", "label": "Where I am right now: emotion mind, reasonable mind, or between"}, {"id": "f2", "type": "textarea", "label": "What emotion mind wants me to do"}, {"id": "f3", "type": "textarea", "label": "What reasonable mind wants me to do"}, {"id": "f4", "type": "textarea", "label": "My wise-mind opening line"}]'::jsonb, array['relationship issues', 'wise mind', 'emotion regulation']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('life-transition-role-renegotiation', 'Life Transition Role Renegotiation', 'couples'::resource_kind, 'A worksheet for a couple to renegotiate who does what after a major life transition shifts old roles.', 'Use it after a job change, move, retirement, or illness to update expectations instead of assuming.', array['Couples']::text[], '30 minutes', 'Roles that worked before a transition — who managed money, who ran the household, who worked outside the home — often stay on autopilot after the transition has already changed the reality on the ground, and resentment builds quietly on both sides. Have each partner complete their columns separately first, then compare in session, and expect at least one role neither partner realizes has gone unclaimed since the change. Revisit this again a few months after the transition, not just once.', '[{"id": "f0", "type": "textarea", "label": "What changed for us, the transition itself"}, {"id": "f1", "type": "textarea", "label": "A role I used to have that no longer fits"}, {"id": "f2", "type": "textarea", "label": "A role my partner used to have that no longer fits"}, {"id": "f3", "type": "textarea", "label": "What I need from my partner now that wasn''t true before"}, {"id": "f4", "type": "textarea", "label": "One role we will explicitly reassign this week"}]'::jsonb, array['relationship issues', 'transitions', 'fairness']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('sibling-peace-treaty-craft', 'Sibling Peace Treaty Craft', 'kids'::resource_kind, 'Siblings decorate and sign a written agreement listing the ground rules that ended their last fight.', 'Use it to turn a repeated sibling conflict into a shared, visible agreement both children helped write.', array['Children']::text[], '25 minutes', 'Do this once things have cooled down, never mid-conflict, and let both children propose rules before you shape the wording, since a treaty they help write gets followed far more than one handed to them. The caregiver''s job afterward is to post the treaty somewhere visible, reference it calmly by name during the next flare-up such as asking what the treaty says, and praise both children when they follow it rather than only stepping in when they don''t.', '[{"id": "f0", "type": "textarea", "label": "What we were fighting about"}, {"id": "f1", "type": "textarea", "label": "One rule I promise to follow"}, {"id": "f2", "type": "textarea", "label": "One rule my sibling promised to follow"}, {"id": "f3", "type": "textarea", "label": "What we will do instead of fighting next time"}, {"id": "f4", "type": "textarea", "label": "A picture or decoration for our treaty"}]'::jsonb, array['relationship issues', 'siblings', 'children']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('trust-generalization-check', 'Trust Generalization Check', 'cbt'::resource_kind, 'A thought record testing whether a no one is safe belief fits the trustworthy people in a client''s life now.', 'Use it to separate a specific past harm from a blanket rule applied to everyone in the present.', array['Adults', 'Teens']::text[], '25 minutes', 'Keep this entirely in the present tense — the prompts ask about current relationships and current evidence, not what happened before, and should never be used to draw out details of past abuse. Clients with this history often carry an efficient but costly rule that protected them once and now isolates them; the aim is not to argue them out of caution but to test the rule against specific people already in their life. Go slowly if the client becomes activated, and return to grounding before ending the session.', '[{"id": "f0", "type": "textarea", "label": "The rule I carry about who can be trusted"}, {"id": "f1", "type": "textarea", "label": "A person in my life now who this rule may not fit"}, {"id": "f2", "type": "textarea", "label": "Evidence for why this person might be safe to trust a little"}, {"id": "f3", "type": "textarea", "label": "Evidence that makes me cautious, even now"}, {"id": "f4", "type": "textarea", "label": "One small, low-risk way to test trust with this person"}, {"id": "f5", "type": "textarea", "label": "What I will do to ground myself if this feels like too much"}]'::jsonb, array['sexual abuse', 'trust', 'thought record']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('trust-rebuilding-values-ladder', 'Trust Rebuilding Values Ladder', 'act'::resource_kind, 'A step-by-step ladder that paces trust and connection toward what a client actually values.', 'Use it to build committed action toward closeness at a pace the client''s fear can tolerate.', array['Adults', 'Teens']::text[], '20 minutes, building over several sessions', 'This stays entirely forward-facing: the client identifies what connection or closeness they want more of now, then builds a ladder of small, willingness-based steps toward it, from lowest to highest fear. It is not an exposure hierarchy aimed at abuse memories and should never ask the client to revisit what happened. Expect the bottom rungs to look smaller than clients think they should need, which is normal, and rushing the ladder tends to backfire more than moving slowly does.', '[{"id": "f0", "type": "textarea", "label": "What I want more of in my relationships, the value underneath this"}, {"id": "f1", "type": "textarea", "label": "A very small step toward that, one I could do this week"}, {"id": "f2", "type": "textarea", "label": "A medium step, further out"}, {"id": "f3", "type": "textarea", "label": "A bigger step I''m working toward, not yet"}, {"id": "f4", "type": "textarea", "label": "What fear tends to show up, and what I''ll do to make room for it"}]'::jsonb, array['sexual abuse', 'values', 'committed action']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('safe-closeness-menu-for-partners', 'Safe Closeness Menu for Partners', 'couples'::resource_kind, 'A menu both partners build together of non-sexual affection that currently feels safe and welcome.', 'Use it to give a couple a concrete, agreed starting point when a history of sexual abuse affects pacing.', array['Couples']::text[], '25 minutes', 'This addresses how one partner''s history shapes intimacy and pacing for the couple, not the history itself, and nothing here should ask either partner to describe what happened. Have each partner list forms of closeness such as hand-holding, sitting back-to-back, a hug at the door, or a check-in text that they currently welcome, are unsure about, or want to hold off on, then compare lists together. Revisit the menu regularly, since what belongs in each column can shift, and remind both partners that either can move something to a different column at any time without needing to explain why.', '[{"id": "f0", "type": "textarea", "label": "A form of closeness that feels good and welcome right now"}, {"id": "f1", "type": "textarea", "label": "A form of closeness I''m unsure about"}, {"id": "f2", "type": "textarea", "label": "A form of closeness I want to hold off on for now"}, {"id": "f3", "type": "textarea", "label": "How I''d like my partner to check in before initiating"}, {"id": "f4", "type": "textarea", "label": "What support I need from my partner if I need to pause"}]'::jsonb, array['sexual abuse', 'intimacy', 'pacing']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('safety-voice-puppet-practice', 'Safety Voice Puppet Practice', 'kids'::resource_kind, 'Children build a simple puppet and use it to rehearse saying no and telling a safe adult.', 'Use it to give a child a rehearsed, playful way to practice body safety rules and telling a trusted adult.', array['Children']::text[], '30 minutes', 'Keep this squarely at the level of general body safety rules and rehearsal, such as practicing a firm no, a loud stop, and telling a safe adult right away, and never use it to ask a child to describe a specific event. The caregiver decorates a puppet alongside the child and takes a turn practicing the same lines, which makes the rehearsal feel like play rather than a test. If a child discloses anything during this activity, stop the exercise and follow your mandated reporting duties right away; this tool is for rehearsal and prevention, not for gathering disclosure details.', '[{"id": "f0", "type": "textarea", "label": "My puppet''s name"}, {"id": "f1", "type": "textarea", "label": "What my puppet says if a touch feels not okay"}, {"id": "f2", "type": "textarea", "label": "Who my puppet''s safe grown-ups are"}, {"id": "f3", "type": "textarea", "label": "What my puppet does if something feels wrong"}, {"id": "f4", "type": "textarea", "label": "A time I want to practice with my puppet again"}]'::jsonb, array['sexual abuse', 'body safety', 'children']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('trusted-grown-up-relay-game', 'Trusted Grown-Up Relay Game', 'game'::resource_kind, 'A relay race where children answer body safety and trusted-adult questions before tagging their teammate.', 'Use it to rehearse body safety rules and naming safe adults in a fast-paced, playful format.', array['Children', 'Groups']::text[], '20 minutes', 'Set up two short relay lines with a stack of simple scenario cards at the far end covering okay or not-okay touch, who counts as a safe adult, and what to say and do, then have each player run down, answer one card correctly with a helping adult''s support if needed, and tag the next teammate. Keep every card at the level of general rules, never a specific event, and end with a group debrief naming each child''s own safe adults out loud. Watch for any child who seems distressed rather than playful and pull them aside gently rather than continuing the game.', '[{"id": "f0", "type": "textarea", "label": "A safety rule I answered correctly"}, {"id": "f1", "type": "textarea", "label": "One of my own safe grown-ups"}, {"id": "f2", "type": "textarea", "label": "Something I want to remember from today''s game"}, {"id": "f3", "type": "textarea", "label": "A question I still have about staying safe"}]'::jsonb, array['sexual abuse', 'body safety', 'group']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('coping-skills-sorted-by-feeling-state', 'Coping Skills Sorted by Feeling State', 'worksheet'::resource_kind, 'A sheet that sorts a client''s coping skills by the internal state they answer, not the situation.', 'Use it to help a client reach for a skill that matches how their body and mind feel right now.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients often have a long list of coping skills but freeze on which one to use, because most lists are organized by situation rather than by internal state. This sheet sorts skills into four columns: numb or shut down, wired or keyed up, spiraling thoughts, and lonely or low. Build the columns together from skills the client has already tried, and press for at least two entries per column before moving on. Revisit it after a hard week and move entries between columns as you learn what actually helps in each state.', '[{"id": "f0", "type": "textarea", "label": "Skills that help when I feel numb or shut down"}, {"id": "f1", "type": "textarea", "label": "Skills that help when I feel wired or keyed up"}, {"id": "f2", "type": "textarea", "label": "Skills that help when my thoughts are spiraling"}, {"id": "f3", "type": "textarea", "label": "Skills that help when I feel lonely or low"}, {"id": "f4", "type": "textarea", "label": "How I can tell which state I am in before I pick a skill"}, {"id": "f5", "type": "textarea", "label": "A skill I want to try adding to one of these columns"}]'::jsonb, array['coping skills', 'emotion regulation', 'self-monitoring']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('coping-skills-in-service-of-values', 'Coping Skills in Service of Values', 'act'::resource_kind, 'Links each coping skill a client uses to the value it clears space to act on afterward.', 'Use it to keep coping skills in service of a valued life rather than an end in themselves.', array['Adults', 'Teens']::text[], '20 minutes', 'This is a defusion move for clients who have plenty of coping skills but use them to disappear from life rather than to re-enter it. For each skill, the client names not just that it lowered distress but what it then let them do that mattered to them, however small. If a client cannot name anything a skill made possible, flag it in session; that is often a sign the skill has become an avoidance strategy rather than a bridge back to a value. Keep the tone curious rather than corrective when that shows up.', '[{"id": "f0", "type": "textarea", "label": "A coping skill I use often"}, {"id": "f1", "type": "textarea", "label": "What it does for me in the moment"}, {"id": "f2", "type": "textarea", "label": "What it lets me do afterward that matters to me"}, {"id": "f3", "type": "textarea", "label": "A time the skill helped me get back to something I value"}, {"id": "f4", "type": "textarea", "label": "A time I used the skill just to disappear, with nothing after it"}, {"id": "f5", "type": "textarea", "label": "One value I want a skill to point back toward this week"}]'::jsonb, array['coping skills', 'values', 'workability']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('skill-stack-sequence-card', 'Skill Stack Sequence Card', 'dbt'::resource_kind, 'A card that orders three DBT skills into a first, backup, and fallback sequence for rising distress.', 'Use it to give a client a rehearsed order of skills rather than a flat list to choose from under pressure.', array['Adults', 'Teens']::text[], '20 minutes', 'Diary cards and skills lists tell a client what is available, but under real distress people rarely scan a full list and pick well. This card has them commit in advance to a first skill (often a body-based one like paced breathing or a TIPP technique), a backup if the first does not land within a few minutes, and a fallback for when distress is still climbing, usually a distraction or self-soothe skill. Rehearse the sequence out loud in session, including what tells the client it is time to move to the next step, and troubleshoot access issues for each one before they leave.', '[{"id": "f0", "type": "textarea", "label": "My first skill to try"}, {"id": "f1", "type": "textarea", "label": "How I will know it is time to move to my backup"}, {"id": "f2", "type": "textarea", "label": "My backup skill"}, {"id": "f3", "type": "textarea", "label": "My fallback skill if distress is still climbing"}, {"id": "f4", "type": "textarea", "label": "What could get in the way of using this sequence"}, {"id": "f5", "type": "textarea", "label": "How this sequence worked the last time I used it"}]'::jsonb, array['coping skills', 'distress tolerance', 'core DBT']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('coping-skills-suitcase-craft', 'Coping Skills Suitcase Craft', 'kids'::resource_kind, 'A child packs a paper suitcase with drawings of coping skills for an upcoming hard moment.', 'Use it to help a child prepare concrete, portable coping tools before a specific stressful event.', array['Children']::text[], '25 minutes', 'Cut a large suitcase shape from card stock with a flap that opens, and have the child draw or cut out small pictures of coping skills to pack inside, framed around one upcoming trip they are nervous about, such as a doctor visit, a first day, or a sleepover. Keep the packing concrete: a picture of a stuffed animal for the self-soothing item, a breathing cloud, a photo of a trusted adult. The caregiver''s job afterward is to actually bring the suitcase along or recreate its contents on the day, and to name out loud which packed skill they are using in the moment so the child sees it modeled.', '[{"id": "f0", "type": "textarea", "label": "What hard moment am I packing for?"}, {"id": "f1", "type": "textarea", "label": "A coping skill I am packing (draw or write it)"}, {"id": "f2", "type": "textarea", "label": "Another coping skill I am packing"}, {"id": "f3", "type": "textarea", "label": "One more thing I am packing"}, {"id": "f4", "type": "textarea", "label": "Who will help me carry my suitcase on the day"}, {"id": "f5", "type": "textarea", "label": "For the grown-up: how we will use the suitcase on the day"}]'::jsonb, array['coping skills', 'children', 'art']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('coping-skills-showdown', 'Coping Skills Showdown', 'game'::resource_kind, 'A bracket-style elimination game where coping skill cards face off and the group votes a round winner.', 'Use it to generate lively debate about what makes a coping skill fit a given moment.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Write eight to sixteen coping skills on cards and set them up in a single-elimination bracket. For each matchup, read a short scenario card and have the group vote which of the two paired skills fits it better; the winner advances. The fun is in the arguing, so let players make a case for an underdog skill before the vote. End with the two finalists facing off on a genuinely hard scenario, then debrief on how the same skill lost in one round and won in another, which is the real point: fit depends on context, not on any skill being universally best.', '[{"id": "f0", "type": "textarea", "label": "Skills we put in our bracket"}, {"id": "f1", "type": "textarea", "label": "A matchup that sparked the most debate"}, {"id": "f2", "type": "textarea", "label": "Our final two skills and the scenario they faced"}, {"id": "f3", "type": "textarea", "label": "What we noticed about the same skill winning in one round and losing in another"}, {"id": "f4", "type": "textarea", "label": "A skill that lost every round for me but I still want to keep"}]'::jsonb, array['coping skills', 'group', 'play']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('fear-origin-timeline', 'Fear Origin Timeline', 'worksheet'::resource_kind, 'Traces when and how a specific fear first took hold and what has kept it going.', 'Use it to build a shared history of the fear before starting hierarchy or exposure work.', array['Adults', 'Teens']::text[], '30 minutes', 'Before building a hierarchy, it helps to know whether a fear arrived through a frightening direct experience, watching someone else react fearfully, being told repeatedly that something was dangerous, or no clear event at all. None of these origins change the plan much, but naming one often reduces the confusion and self-blame clients feel about a fear that seems to have appeared from nowhere. Watch for clients who reach for a dramatic origin story that does not quite fit; a vague or absent memory is common and is fine to leave as such.', '[{"id": "f0", "type": "textarea", "label": "The earliest memory I have connected to this fear"}, {"id": "f1", "type": "textarea", "label": "Was there a specific frightening event, or has it always been there?"}, {"id": "f2", "type": "textarea", "label": "Did anyone close to me react fearfully to this same thing?"}, {"id": "f3", "type": "textarea", "label": "What I was told about this thing growing up"}, {"id": "f4", "type": "textarea", "label": "How the fear has changed in size or reach since it started"}, {"id": "f5", "type": "textarea", "label": "What, if anything, has kept the fear going"}]'::jsonb, array['phobias', 'formulation', 'history']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('fear-generalization-map', 'Fear Generalization Map', 'cbt'::resource_kind, 'Maps how a fear has spread outward from its original object to related situations over time.', 'Use it to find where a fear has generalized so exposure work targets the right layers.', array['Adults', 'Teens']::text[], '25 minutes', 'Specific fears rarely stay contained; a fear of one dog can spread to all dogs, then to the sound of barking, then to walks where a dog might appear. This map starts with the original feared object at the center and has the client add rings outward for each related situation the fear has spread to, in the order it happened if they can recall it. The map often reveals that the outer rings are more avoidable and more impairing day to day than the original trigger, which can shift where exposure work starts.', '[{"id": "f0", "type": "textarea", "label": "The original feared object or situation"}, {"id": "f1", "type": "textarea", "label": "The first related situation the fear spread to"}, {"id": "f2", "type": "textarea", "label": "Situations further removed that now trigger fear too"}, {"id": "f3", "type": "textarea", "label": "Which ring causes the most disruption to my daily life"}, {"id": "f4", "type": "textarea", "label": "A situation I avoid completely because of this spread"}, {"id": "f5", "type": "textarea", "label": "Where I want to start working first, and why"}]'::jsonb, array['phobias', 'exposure', 'formulation']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('stay-in-it-countdown-card', 'Stay-in-It Countdown Card', 'dbt'::resource_kind, 'Pairs a fixed countdown with a distress tolerance skill so a client stays in a feared moment rather than escaping.', 'Use it to give a client a concrete, timed alternative to escaping a feared situation early.', array['Adults', 'Teens']::text[], '15 minutes', 'Escaping a feared situation the moment distress spikes is what keeps a phobia intact, but telling a client to simply tolerate the feeling rarely works on its own. This card sets a specific count, such as sixty seconds or ten breaths, paired with one distress tolerance skill the client will run during that count, then has them log where their fear actually peaked and where it landed by the end of the count. Most clients are surprised the peak arrives sooner than they expect. Use short counts at first and lengthen them only as the client''s confidence in the pairing grows.', '[{"id": "f0", "type": "textarea", "label": "The situation I am staying in"}, {"id": "f1", "type": "textarea", "label": "My countdown length"}, {"id": "f2", "type": "textarea", "label": "The distress tolerance skill I am running during the count"}, {"id": "f3", "type": "textarea", "label": "Fear level at the start of the count (0 to 10)"}, {"id": "f4", "type": "textarea", "label": "Fear level at the end of the count (0 to 10)"}, {"id": "f5", "type": "textarea", "label": "What I noticed about where the fear peaked"}]'::jsonb, array['phobias', 'distress tolerance', 'exposure']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('phobia-accommodation-reduction-plan', 'Phobia Accommodation Reduction Plan', 'couples'::resource_kind, 'Helps a couple name the accommodations one partner makes for the other''s fear and plan to reduce them gradually.', 'Use it to shrink the accommodations that unintentionally keep a partner''s fear in place.', array['Couples']::text[], '30 minutes', 'When one partner has a specific fear, the other often quietly takes over related tasks entirely, from handling anything that flies to always driving on the highway, which eases short-term distress but keeps the fear intact and can breed quiet resentment on both sides. This plan has the fearful partner name each accommodation and rate how much it helps versus how much it reinforces avoidance, while the accommodating partner names what that accommodating actually costs them. Agree together on one accommodation to reduce first, and what support looks like as the task shifts back.', '[{"id": "f0", "type": "textarea", "label": "Partner with the fear: tasks my partner currently handles because of my fear"}, {"id": "f1", "type": "textarea", "label": "Partner with the fear: which of these I could start taking back on, with support"}, {"id": "f2", "type": "textarea", "label": "Accommodating partner: what taking on these tasks costs me"}, {"id": "f3", "type": "textarea", "label": "Accommodating partner: what support I can offer as my partner takes a task back"}, {"id": "f4", "type": "textarea", "label": "The one accommodation we are agreeing to reduce first"}, {"id": "f5", "type": "textarea", "label": "How we will check in with each other as this changes"}]'::jsonb, array['phobias', 'accommodation', 'relationship issues']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('whose-fear-is-it-anyway', 'Whose Fear Is It Anyway', 'game'::resource_kind, 'A guessing game where anonymous fears are read aloud and the group guesses who wrote each one.', 'Use it to normalize specific fears and lower shame before hierarchy work begins.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Each player writes one specific fear on an unsigned card and drops it in a container. Shuffle and read the fears aloud one at a time, letting the group guess who wrote each before the writer reveals themselves. The reveals usually surprise people, since confident-seeming group members often turn out to have the most vivid fears, and that mismatch does most of the normalizing work. Close by having each player pick one fear from the pile, their own or someone else''s, and name where it might sit on a hierarchy from mild to severe.', '[{"id": "f0", "type": "textarea", "label": "The fear I wrote on my card"}, {"id": "f1", "type": "textarea", "label": "A fear someone else shared that surprised me"}, {"id": "f2", "type": "textarea", "label": "How it felt to have my fear guessed, or guessed wrong"}, {"id": "f3", "type": "textarea", "label": "What I noticed about how common specific fears turned out to be"}, {"id": "f4", "type": "textarea", "label": "Where my own fear might sit on a hierarchy from mild to severe"}]'::jsonb, array['phobias', 'group', 'play']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('body-image-trigger-map', 'Body Image Trigger Map', 'worksheet'::resource_kind, 'Maps the specific situations, people, and settings that spike appearance-focused distress.', 'Use it to identify concrete triggers rather than leaving body image distress as a vague, constant backdrop.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients often describe body image distress as constant, but it usually spikes around specific, nameable triggers: certain lighting, particular clothing, specific people''s comments, or particular apps at particular times of day. This map has the client list triggers across a few categories and rate the intensity each brings up, which turns an overwhelming, undifferentiated feeling into something with edges the client can plan around. Use the map to choose one or two triggers to work with directly rather than trying to address everything at once.', '[{"id": "f0", "type": "textarea", "label": "Places or settings that spike appearance-focused distress"}, {"id": "f1", "type": "textarea", "label": "People or comments that spike it"}, {"id": "f2", "type": "textarea", "label": "Specific times of day or situations that spike it"}, {"id": "f3", "type": "textarea", "label": "Apps, sites, or media that spike it"}, {"id": "f4", "type": "textarea", "label": "Which trigger feels most intense, rated 0 to 10"}, {"id": "f5", "type": "textarea", "label": "One trigger I want to work on first"}]'::jsonb, array['body image', 'triggers', 'self-monitoring']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('appearance-rule-cost-benefit-ledger', 'Appearance Rule Cost-Benefit Ledger', 'cbt'::resource_kind, 'Weighs what a client''s strict appearance-related rule actually gives them against what it costs.', 'Use it to loosen the grip of a specific appearance rule by making its real costs visible.', array['Adults', 'Teens']::text[], '25 minutes', 'Clients with body image concerns often live by unspoken rules, such as never leaving the house without makeup or always wearing certain clothing to hide a feature they dislike. This ledger picks one such rule and lays out what the client believes it protects them from against what it actually costs in time, spontaneity, and mental energy. The point is not to argue the client out of the rule in one sitting, but to make the trade explicit enough that a small, time-limited experiment with bending it becomes thinkable.', '[{"id": "f0", "type": "textarea", "label": "The appearance rule I am examining"}, {"id": "f1", "type": "textarea", "label": "What I believe would happen if I broke this rule"}, {"id": "f2", "type": "textarea", "label": "What this rule gives me or protects me from"}, {"id": "f3", "type": "textarea", "label": "What this rule costs me in time, energy, or freedom"}, {"id": "f4", "type": "textarea", "label": "A small, time-limited way I could bend this rule"}, {"id": "f5", "type": "textarea", "label": "What I noticed after trying it"}]'::jsonb, array['body image', 'core beliefs', 'self-criticism']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('appearance-story-defusion-card', 'Appearance Story Defusion Card', 'act'::resource_kind, 'Practices holding an appearance-critical thought as a passing story rather than a fact to act on.', 'Use it to build distance from appearance-critical thoughts without arguing them into being false.', array['Adults', 'Teens']::text[], '15 minutes', 'Rather than disputing an appearance-critical thought as true or false, this card has the client notice it and relabel it as a story their mind is telling, using the standard defusion frame of "I''m noticing my mind is telling me the story that...". Practice this in session first with a mild example before the client tries it on a stronger one; the wording feels awkward at first and clients often want to skip straight to arguing the content instead. The goal is distance from the thought, not agreement or disagreement with it.', '[{"id": "f0", "type": "textarea", "label": "The appearance-critical thought I want to practice with"}, {"id": "f1", "type": "textarea", "label": "The same thought reframed as: I''m noticing my mind is telling me the story that..."}, {"id": "f2", "type": "textarea", "label": "How it felt to hold the thought this way instead of arguing with it"}, {"id": "f3", "type": "textarea", "label": "A moment this week I could try this with a new thought"}, {"id": "f4", "type": "textarea", "label": "What I did instead of acting on the thought"}]'::jsonb, array['body image', 'defusion', 'self-talk']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('shared-media-feed-audit', 'Shared Media Feed Audit', 'couples'::resource_kind, 'Has both partners review what appearance-focused content they follow and agree on changes together.', 'Use it to turn media habits that fuel comparison into something a couple manages together.', array['Couples']::text[], '25 minutes', 'Appearance-focused comparison is often fed by media one partner scrolls alone, and the other partner may not know which accounts or content are hardest on their partner''s self-perception. This audit has each partner separately list a few accounts or types of content that leave them feeling worse about their appearance, then share the lists with each other. From there they agree on one concrete change each, such as muting an account or adding a different kind of content, and one way the other partner can check in without it turning into surveillance.', '[{"id": "f0", "type": "textarea", "label": "Partner A: content or accounts that leave me feeling worse about how I look"}, {"id": "f1", "type": "textarea", "label": "Partner B: content or accounts that leave me feeling worse about how I look"}, {"id": "f2", "type": "textarea", "label": "What surprised each of us about the other''s list"}, {"id": "f3", "type": "textarea", "label": "One change each partner is making to their own feed"}, {"id": "f4", "type": "textarea", "label": "How we will check in on this without it feeling like monitoring"}]'::jsonb, array['body image', 'media', 'communication']::text[], '2026-09-23T15:00:00+00:00'::timestamptz),
  ('kind-mirror-frame-craft', 'Kind Mirror Frame Craft', 'kids'::resource_kind, 'A child decorates a frame to keep near a mirror at home, filled with kind things to say to themselves.', 'Use it to build a habit of kind self-talk in the exact moment appearance-focused thoughts tend to show up.', array['Children']::text[], '25 minutes', 'Give the child a plain cardboard or paper frame, small enough to lean near a mirror at home, and have them decorate it and write or draw a few kind phrases inside, things they can say to themselves rather than comments about how they look. The caregiver''s job is to place the frame near a mirror the child uses daily and say one of the phrases aloud themselves sometimes, modeling that grown-ups need reminders too. If the child leans toward harsh self-comments already, redirect gently toward phrases about how they treat others or what they enjoy doing.', '[{"id": "f0", "type": "textarea", "label": "A kind thing I can say to myself"}, {"id": "f1", "type": "textarea", "label": "Another kind thing I can say to myself"}, {"id": "f2", "type": "textarea", "label": "Where we will put my frame"}, {"id": "f3", "type": "textarea", "label": "For the grown-up: a kind phrase you will say out loud near the mirror too"}, {"id": "f4", "type": "textarea", "label": "How I felt after using my frame this week"}]'::jsonb, array['body image', 'children', 'self-talk']::text[], '2026-09-23T15:00:00+00:00'::timestamptz)
